We discuss more about \cref{eq:optim}, In particular:
\begin{enumerate}
  \item when $\gamma = 0$, the optimization problem is equivalent to solely maximizing the initial loss $J\left(x_{t}^{i}, y\right)$;
  \item when $\gamma = 1$, it aims at solely maximizing the perturbed point loss $J\left(x_{t}^{*}, y\right)$;
  \item when $\gamma \in (0,1)$, the optimization problem simultaneously balances both the initial loss and the perturbed point loss.
\end{enumerate}
The gradient of the current loss function can be formulated as follows:
\begin{equation}
    \nabla_{x_{t}^{i}} \mathcal{L}\left(x_{t}^{i}, y\right) \approx(1-\gamma) \cdot \nabla_{x_{t}^{i}} J\left(x_{t}^{i}, y\right)+\gamma \cdot \nabla_{x_{t}^{i}} J\left(x_{t}^{*}, y\right).
\end{equation}

Next, ResPA acquires the average gradient $\bar{g} _{t+1}$ over $N$ sampling points to be formulated as:
\begin{equation}
\bar{g}_{t+1}   = \frac{1}{N} \sum_{i=1}^{N}   \nabla_{x_{t}^{i}} \mathcal{L}\left(x_{t}^{i}, y \right),
\end{equation}
where $N$ represents the number of sampling points.
Next, we compute the EMA of the average gradient $\bar{g} _{t+1}$ to obtain the first-order moment $e_{t+1}$, which will be substituted into \cref{eq:lishi} in the next iteration to update the reference gradient $M_{t+1}$. The update rule for $e_{t + 1} $ is given by:
\begin{equation}
e_{t+1} = \theta\cdot e_t+(1-\theta )\cdot \bar{g} _{t+1},
\label{eq:eee}
\end{equation}
where $\theta$ is the exponential decay factor. Then the average gradient $\bar{g} _{t+1}$ is employed to update the momentum $g_{t+1}$, yielding:
%\begin{equation}
%    \boldsymbol{g}_{t+1}=\mu \cdot\boldsymbol{g}_{t}+\frac{\overline{\boldsymbol{g}}_{t+1}}{\left\|\overline{\boldsymbol{g}}_{t+1}\right\|_{1}},
%\end{equation}
\begin{equation}
    g_{t+1}=\mu \cdot g_{t}+\frac{\overline{g}_{t+1}}{\left\|\overline{g}_{t+1}\right\|_{1}},
\end{equation}
where $\mu$ is the decay factor. Finally, the adversarial samples $x_{t+1}^{a d v}$ are updated as follows:
\begin{equation}
    x_{t+1}^{a d v}=Clip_x^{\epsilon}(x_{t}^{a d v}+\alpha \cdot  \operatorname{sign}\left(g_{t+1}\right)),
\end{equation}
where $\operatorname{sign}(\cdot)$ is the sign function, $Clip_x^{\epsilon}(\cdot)$ denotes that the generated adversarial image is constrained within the $\epsilon$-ball neighborhood of the original image $x$, and $\alpha$ denotes the predetermined step size.


