\textbf{Retrieval loss}.
Given a batch of $B$ (music, video) pairs, the model needs to generate and optimize $B\times B$ similarities.
We optimize the model parameters using InfoNCE \cite{oord2018representation}, a symmetric cross-entropy loss, applied to the similarity scores between temporal aggregation features, and formulate the entire process similarly to \cite{radford2021learning}:
\begin{align}
\mathcal{L}_{m2v} &= -\frac{1}{B} \sum_k^B{\log \frac{\exp(s(h(m_k), h(v^+)) / \tau)}{\sum_{j=1}^B{\exp(s(h({m_k}), h(v_j)) / \tau)}}}, \\
\mathcal{L}_{v2m} &= -\frac{1}{B} \sum_k^B{\log \frac{\exp(s(h(m^+), h(v_k)) / \tau)}{\sum_{j=1}^B{\exp(s(h(m_j), h(v_k)) / \tau)}}}, \\
\mathcal{L}_{\text{agg}} &= \mathcal{L}_{m2v} + \mathcal{L}_{v2m},
\end{align}
where $s(h(m), h(v))$ is the cosine similarity function, and $\tau$ is a learnable temperature parameter.

To balance and complement the optimization, we replace $h(M)$ with $\mbox{mean-pooling}(\{\tilde{s}_i\}_{i=1}^S)$ in $\mathcal{L}_{\text{agg}}$ and formulate as loss $\mathcal{L}_{\text{pooled}}$. The final retrieval loss is the sum of both losses:
\begin{align}
\mathcal{L}_{\text{retr}} &= \mathcal{L}_{\text{pooled}} + \mathcal{L}_{\text{agg}}. \label{eq:loss_retrieval}
\end{align}
}

\delete{\textbf{Cross-modal contrastive learning.}
Given a batch of $B$ (music, video) pairs, the model needs to generate and optimize $B\times B$ similarities. We apply InfoNCE \cite{oord2018representation}, a symmetric cross-entropy loss, over these similarity scores to optimize the model parameters,
\begin{align}
\mathcal{L}_{m2v} &= -\frac{1}{B} \sum_k^B{\log \frac{\exp(s(\hat{\mathbf{y}}_{m_k}, \hat{\mathbf{y}}_v^+) / \tau)}{\sum_{j=1}^B{\exp(s(\hat{\mathbf{y}}_{m_k}, \hat{\mathbf{y}}_{v_j}) / \tau)}}}, \\
\mathcal{L}_{v2m} &= -\frac{1}{B} \sum_k^B{\log \frac{\exp(s(\hat{\mathbf{y}}_m^+, \hat{\mathbf{y}}_{v_k}) / \tau)}{\sum_{j=1}^B{\exp(s(\hat{\mathbf{y}}_{m_j}, \hat{\mathbf{y}}_{v_k}) / \tau)}}}, \\
\mathcal{L} &= \mathcal{L}_{m2v} + \mathcal{L}_{v2m}.
\end{align}
where $s(\hat{\mathbf{y}}_m, \hat{\mathbf{y}}_v)$ is the cosine similarity function, and $\tau$ is a learnable temperature parameter.
% and it is an important parameter to improve the rank score.
}

\delete{The loss $\mathcal{L}$ is the sum of video-to-text loss $\mathcal{L}_{m2v}$ and text-to-video loss $\mathcal{L}_{v2m}$. Notably, because multiple videos may share the same complete music, the positive music sample $\hat{\mathbf{y}}_m^+$ in $\mathcal{L}_{v2m}$ refers to all music instances corresponding to $v_k$ in the batch instead of just $\hat{\mathbf{y}}_{m_k}$.}




\delete{
\textbf{Detection loss.} Building upon prior research \cite{carion2020detr,lei2021momentdetr,moon2023dqdetr}, our framework employs a composite detection loss $\mathcal{L}_{\text{det}}$ to optimize temporal boundary alignment between prediction and ground truth moments.
The loss function combines two complementary loss components: $\text{L1}$ regression loss for measuring mean absolute error and a generalized IoU loss \cite{rezatofighi2019giou} for boundary refinement. The complete detection loss is formulated as:
\begin{align}
\mathcal{L}_{\text{det}} = \lambda_{\text{L1}}||y_{\text{det}}-p_{\text{det}}|| + \lambda_{\text{gIoU}} \mathcal{L}_{\text{gIoU}}(y_{\text{det}}, p_{\text{det}}). \label{eq:loss_detection}
\end{align}
Here, $y_{\text{det}}=(y_c, y_w)\in [0,1]^2$ represents the ground truth moment parameters, where $y_c$ denotes the normalized center position and $y_w$ the normalized temporal width relative to the input music duration. Similarly, $p_{\text{det}}=(p_c, p_w)$ corresponds to the predicted moment parameters. The hyperparameters $\lambda_{\text{L1}}$, $\lambda_{\text{gIoU}}\in \mathbb{R}$ regulate the trade-off between the two terms.
While adapted for 1D temporal intervals rather than 2D spatial boxes as in \cite{rezatofighi2019giou,carion2020detr}, the IoU loss $\mathcal{L}_{\text{gIoU}}$ maintains the original formulation.
}


\delete{
\textbf{Overall loss.} The task-specific composite final loss $\mathcal{L}_{\text{overall}}$ through a linear combination of \cref{eq:loss_retrieval} and \cref{eq:loss_detection} to unify optimization objectives:
\begin{align}
\mathcal{L}_{\text{overall}} = \lambda_{\text{retr}} \mathcal{L}_{\text{retr}} + \lambda_{\text{det}} \mathcal{L}_{\text{det}}.
\end{align}
Following \cite{carion2020detr}, we apply moment losses to every decoder layer.
}

