\subsection{Modeling the Inherent Structures of Videos}

\paragraph{Formulating {outputs of video LLMs} by events.} 

{
Given the instruction $\mathbf{I}$ and video visual inputs $\mathbf{F}$, we represent the outputs of video LLMs $\mathbf{R}$ as a series of events $\{ e_1, e_2, \cdots, e_K \}$, with each event $e_k = (t_k, s_k, c_k)$ encompassing timestamps $t_k$, salient scores $s_k$, and textual captions $c_k$. In summary, we have
\begin{align}
    \mathbf{R} = \{ e_1, e_2, \cdots, e_K \} = \{ (t_k, s_k, c_k) | 1 \le k \le K \} \, .
\end{align}
}
% Given a video $\mathbf{V}$, we represent the video $\mathbf{V}$ as a series of events $\{ e_1, e_2, \cdots, e_K \}$, with each event $e_k = (t_k, s_k, c_k)$ encompassing timestamps $t_k$, salient scores $s_k$, and textual captions $c_k$. In summary, we have
