%     \mathbf{V} = \{ e_1, e_2, \cdots, e_K \} = \{ (t_k, s_k, c_k) | 1 \le k \le K \} \, .
% \end{align}
\paragraph{Causal event modeling framework.} To effectively utilize the knowledge of pretrained LLMs, the design of \framework shares the underlying intuition of causal language modeling, as formulated in the subsequent equation~\footnote{Theoretically, the order of time, score, and text will not impact the results. We select one order here.}.
\begin{align}
    \mathcal{P}(e_k | e_{1:k-1}, \mathbf{I}, \mathbf{F}) & = 
    \mathcal{P}(t_k, s_k, c_k | e_{1:k-1}, \mathbf{I}, \mathbf{F}) \, , \nonumber \\
    & = \mathcal{P}(t_k | e_{1:k-1}, \mathbf{I}, \mathbf{F})
    \mathcal{P}(s_k | t_k, e_{1:k-1}, \mathbf{I}, \mathbf{F}) \mathcal{P}(c_k | s_k, t_k, e_{1:k-1}, \mathbf{I}, \mathbf{F}) \, ,
    \label{equ:next-event-prediction}
\end{align}
% where $\mathbf{I}$ indicates the textural instructions, and $\mathbf{F}$ indicates the visual frame inputs. 
The next event $e_k$ is determined by textural instructions, visual inputs, and previous events. 
We can find that \framework framework aligns well with the video structure (Figure~\ref{fig:video-structure-illustration}):
(1) timestamps, salient scores, and textual captions are sequentially decoded within each event;
(2) events are then ordered by timestamps.


