  commentstyle=\fontsize{7.2pt}{7.2pt}\color{codeblue},
  keywordstyle=\fontsize{7.2pt}{7.2pt},
%  frame=tb,
}
\begin{lstlisting}[language=python]
# B: batch size; S: sequence length 
# H: number of attention heads;
# K: number of target dominant tokens
# CLS_IDX: Index of the CLS token
# SELECT_LAYER: Selected layer for Visual Token

# set the output_attentions=True to get the attention
output = vision_tower(images, output_hidden_states=True, output_attentions=True)

#attn in shape (B, H, S, S)
attn = output.attentions[SELECT_LAYER]

#attn in shape (B, H, S, S)
vanilla_tokens = output.hidden_states[SELECT_LAYER]

#The attention received by each token
#If no CLS, use mean calculate received attention
attn_rec = attn[:, :, cls_idx, cls_idx+1:].sum(dim=1)

# Select K Dominant Tokens
_, topk_idx = attn_rec.topk(K, dim=1) 

# Concat with the CLS token
dominant_idx = cat(CLS_IDX, topk_idx+1)

# filter the Dominant Tokens
dominant_tokens = vanilla_tokens.filter(dominant_idx)

\end{lstlisting}

\end{algorithm}

\mypara{Computation Complexity.}
Evaluating the computational complexity of VLMs requires examining key components such as the self-attention mechanism and the feed-forward network (FFN). The total floating-point operations (FLOPs) can be expressed as: 
$$
\text{Total FLOPs} = T \times (4nd^2 + 2n^2d + 2ndm)
$$
where $T$ is the number of transformer layers, $n$ is the sequence length, $d$ is the hidden dimension size, and $m$ represents the intermediate size of the FFN. 

This equation shows that computational complexity is strongly influenced by the sequence length $n$. In typical VLM tasks, the sequence length is defined as $n = n_{\text{sys}} + n_{\text{img}} + n_{\text{question}}$, with $n_{\text{img}}$ often being much larger than the other two, sometimes by a factor of 20.  
Thus, \textbf{reducing $n_{\text{img}}$} is essential for improving the efficiency of VLMs. 
\subsection{Redundancy Observation}
\label{sec:observe}
In popular Vision Language Models like LLaVA and Mini-Gemini, the number of vision tokens far exceeds that of text tokens, consuming substantial computational resources. To assess whether all these tokens are necessary, we conducted a pilot study on the visual tokens generated by commonly used vision encoders, CLIP and SigLIP. 

Specifically, we randomly sampled one image and visualized the attention of each token from the Vision Encoder's -2 layer, which is the selected layer for obtaining input visual tokens in most VLMs, such as the LLaVA.
As shown in Fig.~\ref{fig:teaser}, both CLIP and SigLIP exhibit an attention pattern concentrated on a limited number of tokens, while the majority of visual tokens receive minimal attention. 
Furthermore, to demonstrate that the attention focusing on only a few tokens is a normal phenomenon, we analyze the distribution of attention weights on the TextVQA validation set. As shown in Fig.~\ref{fig:teaser},  most visual tokens receive very low attention, with weights close to zero, while only a few tokens hold higher attention weights.
To show this phenomenon’s prevalence, we include more visualizations in Appendix~\ref{sec:visual-redundancy}.

Based on this observation, we find that most visual tokens with low attention weights contribute little information and add significant redundancy. Only a few visual tokens aggregate a substantial amount of information and merit focused attention; we refer to these as the dominant visual tokens. 
Therefore, to reduce redundancy, we focus on selecting the most informative tokens—such as the dominant visual tokens—while discarding less informative ones to reduce the overall token count.

