\begin{algorithm}[t]
    \caption{{\sname}: Self-refining anonymizer training}
    \label{alg:seal}
    \resizebox{0.95\textwidth}{!}{ 
    \begin{minipage}{\textwidth} 
        \begin{algorithmic}[1]
        \Require Dataset $\mathcal{D}$, attributes to anonymize $\mathcal{P}$, anonymizer $\mathcal{M}_\text{anon}$, attribute inference model $\mathcal{M}_\text{priv}$, utility evaluator $\mathcal{M}_\text{util}$, loss coefficients $\lambda$s, target model $\pi_\theta$
        \vspace{0.05in}\hrule\vspace{0.05in}

        \Statex \textcolor{gray}{// Step 1: Trajectory generation via simulated anonymization}
        \State Initialize $\mathcal{T} \gets \emptyset$
        \For{each $x_0 \in \mathcal{D}$}
            \State $\mathcal{U}_{0} \gets \mathcal{M}_\text{util}(x_0, x_0)$; $\mathcal{P}_{0} \gets \mathcal{M}_\text{priv}(x_{0}, \mathcal{P})$; $\tau \gets \{( x_{0}, \mathcal{P}_{0}, \mathcal{U}_{0}) \}$
            \For{$t = 0$ to $T-1$} %
                \State $x_{t+1} \gets \mathcal{M}_\text{anon}(x_{t}, \mathcal{P}_t)$; $\mathcal{U}_{t+1} \gets \mathcal{M}_\text{util}(x_0, x_{t+1})$; $\mathcal{P}_{t+1} \gets \mathcal{M}_\text{priv}(x_{t+1}, \mathcal{P})$
                \State $\tau \gets \tau \cup \{( x_{t+1}, \mathcal{P}_{t+1}, \mathcal{U}_{t+1}) \}$
            \EndFor
            \State $\mathcal{T} \gets \mathcal{T} \cup \{ \tau \}$
        \EndFor

        \Statex \textcolor{gray}{// Step 2: Task adaptation via SFT}
        \State Initialize $\mathcal{D}_{\text{anon}} \gets \emptyset$; $\mathcal{D}_{\text{priv}} \gets \emptyset$; $\mathcal{D}_{\text{util}} \gets \emptyset$
        \For{each $\tau \in \mathcal{T}$} %
            \State $\mathcal{D}_{\text{anon}} \gets \mathcal{D}_{\text{anon}} \cup \{ (x_i, x_j) \,\mid\, 0 \leq i < j \leq T,\ p(s_j) > p(s_i),\ u(s_j) \geq u(s_i) \}$
            \State $\mathcal{D}_{\text{priv}} \gets \mathcal{D}_{\text{priv}} \cup \{ (x_i, \mathcal{P}_i) \,\mid\, s_i \in \tau \}$; $\mathcal{D}_{\text{util}} \gets \mathcal{D}_{\text{util}} \cup \{ (x_i, \mathcal{U}_i) \,\mid\, s_i \in \tau \}$
        \EndFor
        \State $\theta \gets \argmin_\theta\,\lambda_{\text{anon}} \cdot \mathcal{L}_{\text{anon}}(\mathcal{D}_{\text{anon}}) + \lambda_{\text{priv}} \cdot \mathcal{L}_{\text{priv}}(\mathcal{D}_{\text{priv}}) + \lambda_{\text{util}} \cdot \mathcal{L}_{\text{util}}(\mathcal{D}_{\text{util}})$

        \Statex \textcolor{gray}{// Step 3: Preference Learning via DPO}
        \State Initialize $\mathcal{D}_{\text{pref}} \gets \emptyset$
        \For{each $\tau \in \mathcal{T}$} %
            \State $\mathcal{D}_{\text{pref}} \gets \mathcal{D}_{\text{pref}} \cup \{ (x_i, x_w, x_l) \,\mid\, 0 \leq i < w, l \leq T,\ p(s_w) > p(s_l),\ u(s_w) \geq u(s_l) \}$
        \EndFor
        \State $\theta \gets \argmin_\theta\,\mathcal{L}_\text{DPO}(\mathcal{D}_{\text{pref}})$
        \State \Return $\pi_\theta$
    \end{algorithmic}
