\noindent \textbf{Automatic group allocation.} 
The primary challenge in allocating group sizes lies in identifying the correlation between the group size of each layer and the final generation performance of the diffusion model. Previous works on mixed precision quantization focus on identifying sensitivity indicators~\citep{li2021brecq, tang2022mixed} for each layer, such as the MSE between the quantized layer and the full precision layer, and then transforming this into an integer linear programming (ILP) problem for optimization. However, we find that a smaller MSE does not necessarily correspond to a reduced performance degradation for DiT quantization, indicating that the previous methods may be ineffective.

To this end, we directly use the FID as our metric for image generation, defined as follows:
\begin{equation}
\label{Eq2}
    L(\mathbf{g}) = \text{FID}(R, G_{\mathbf{g}}).
\end{equation}
Similarly, for video generation models, we use the FVD as our metric:
\begin{equation}
\label{Eq3}
    L(\mathbf{g}) = \text{FVD}(R, G_{\mathbf{g}}),
\end{equation}
where $\mathbf{g} = \{g_1, g_2, \dots,
g_N\}$
 is the layer-wise group size configuration and $N$ is the number of quantized layers. 
 \(R\) and \(G_{\mathbf{g}}\) denote the real samples and the samples generated by the quantized model, respectively.
We then employ an evolutionary algorithm to optimize the following objective function:
\begin{equation}
\label{Eq4}
    {\bf{g}}^{\ast} = \argmin_{\mathbf{g}} L(\mathbf{g}) , \ \ \text{s.t. } B({\bf{g}}) \le N_{bitops},
\end{equation}
where \(B(\cdot)\) is the measurement of bit-operations (BitOps), and \(N_{bitops}\) is the predefined threshold. 

This approach allows us to better capture the nuanced impacts of group size on quantization performance, leading to improved outcomes in both efficiency and image quality. The algorithm is located in Alg.~\ref{alg:alg1}.

\begin{algorithm}[t!]
    \caption{Automatic quantization granularity allocation of Q-DiT}
    \label{alg:alg1}
    \KwIn{Group size search space $\mathcal{S}_g$; number of layers $L$; population size $N_p$; iterations $N_{iter}$; mutation probability $p$; Constraint $N_{bitops}$}
    Initialize population $\mathcal{P}=\{\mathbf{g}^j\}_{j=1}^{N_p}$, where each element in configuration $\mathbf{g}^j \in \mathbb{R}^L$ is  randomly selected from $\mathcal{S}_g$;\\
    % Randomly initialize population $\mathcal{P}$ with $N_p$ candidates, where each candidate is a group size configuration $\mathbf{g}$  \;
    Initialize TopK candidate set $\mathcal{S}_{\text{TopK}}= \emptyset$\;
    \For{$t=1,2,\dots, N_{iter}$}
          {
            \For{$i=1,2,\dots, N_{p}$}
            {Calculate FID (or FVD) for each configuration $\mathbf{g}^j$ based on Eq.~\ref{Eq2} (or Eq.~\ref{Eq3})\;}
            Update $\mathcal{S}_{\text{TopK}}$ with $K$ configurations, according to ranked FID (or FVD) scores\;
            Clear population $\mathcal{P} = \emptyset$\;
            \Repeat{$|\mathcal{P}|$ = $N_{p}/2$          
            }{
                $\mathbf{g}_{cross} = $ CrossOver($\mathcal{S}_{\text{TopK}}$) with probability $1-p$\;
                Append $\mathbf{g}_{cross}$ to $\mathcal{P}$ if $B(\mathbf{g}_{cross})<N_{bitops}$\;
            }
            \Repeat{ $|\mathcal{P}|$ = $N_{p}$          
            }{
                $\mathbf{g}_{mutate} = $ Mutate($\mathcal{S}_{\text{TopK}}$) with probability $p$\;
                Append $\mathbf{g}_{mutate}$ to $\mathcal{P}$ if $B(\mathbf{g}_{mutate})<N_{bitops}$\;
            }
          }
    Get the best group size configuration $\mathbf{g}^{\text{best}}$, and use it to quantize the model\;
    \textbf{return} quantized model
\end{algorithm}

\subsection{Sample-wise Dynamic Activation Quantization}
In UNet-based diffusion quantization, previous studies either allocate a set of quantization parameters for all activations at each timestep~\citep{he2023efficientdm} or design a multi-layer perceptron (MLP)~\citep{so2024temporal} to predict quantization parameters based on the timestep. However, due to {\bf observation 2}, these methods are not compatible with our fine-grained quantization because assigning quantization parameters to each group at every timestep results in considerable memory overheads. Specifically, for a sampler with 50 timesteps, the memory overhead could reach up to 39\% of the full-precision model's size.

Inspired by the recent work in LLM optimization~\citep{wu2023zeroquant}, we design an on-the-fly dynamic quantization approach for activations. 
Specifically, during inference, the quantization parameters for each group of the activations are calculated based on their {\tt min-max} values. For a given sample $i$ at timestep $t$, the quantization parameters for the activation $\mathbf{x}_{i,t}$ can be expressed as:
\begin{align} \label{eq:Eq4}
s_{i,t} &= \frac{\max(\mathbf{x}_{i,t}) - \min(\mathbf{x}_{i,t})}{2^b - 1}, \\
Z_{i,t} &= - \left\lfloor \frac{\min(\mathbf{x}_{i,t})}{s_{i,t}} \right\rceil.
\end{align}
Furthermore, we integrate the dynamic quantization with {\tt min-max} computation into the prior operator, which can benefit from the operator fusion and the overhead becomes negligible compared to the costly matrix multiplications in transformer blocks. 
