\begin{small}
\begin{equation}
\mathcal{L}_{\text{adaptive}} = \sum_{(x,y)} M_{\text{guide}}(x,y) \cdot \mathcal{L}(D_{t-1}, D_{\text{incomplete}})(x, y),
\end{equation}
