\subsection{Background}\label{sec:bg}

\textbf{Diffusion process.} Given a source data point $\bm{x}_0^{\rm src}\sim p_0^{\rm src}$, diffusion models $\epsilon_\theta$~\cite{ddpm} gradually transform $p_0^{\rm src}$ into a Gaussian noise distribution $N(\bm{0}, \bm{I})$ through a $T$-step forward diffusion process.  At each timestep ${t}\in \{1,2,\cdots,T\}$, the intermediate state $\bm{x}_t^{\rm src}\sim p_t^{\rm src}$ is computed as:
\begin{equation}
    \bm{x}_t^{\rm src} = \sqrt{1-\beta_t}\bm{x}_{t-1}^{\rm src} + \sqrt{\beta_t} \bm{\epsilon}_t,
\label{eq:xt}
\end{equation}
where $\bm{\epsilon}_t$ is random Gaussian noise and $\beta_t \in (0, 1)$ represents the diffusion rate at step $t$. By defining $\alpha_t = 1-\beta_t$, $\overline{\alpha_t} = \prod_{t=1}^{T}\alpha_t$ and $\bm{\epsilon} \sim N(\bm{0}, \bm{I})$, we obtain:
\begin{equation}
    \bm{x}_t^{\rm src} 
     = \sqrt{\overline{\alpha_t}}\bm{x}_{0}^{\rm src} + \sqrt{1-\overline{\alpha_t}} \bm{\epsilon}.
\label{eq:xt2}
\end{equation}

The reverse diffusion process recovers a clean $\widehat{\bm{x}_0^{\rm src}}$ by progressively removing noise from $\bm{x}_T^{\rm src}$:
\begin{equation}
    \widehat{\bm{x}_{t-1}^{\rm src}} = 
    \frac{1}{\sqrt{\alpha_t}}(\widehat{\bm{x}_{t}^{\rm src}}-\frac{1-\alpha_t}{\sqrt{1-\overline{\alpha_t}}}\epsilon_\theta(\widehat{\bm{x}_t^{\rm src}}, t)) + \sigma_t \bm{\epsilon},
\label{eq:xt-1}
\end{equation}
where $\sigma_t$ is the posterior noise variance~\cite{ddpm}. 
