\subsection{Surfel-Based RGB-SPAD Rendering}

% \vspace{2mm}
% \noindent
\textbf{Gaussian Surfels.} We represent the 3D scene as a composition of Gaussian surfel primitives \cite{dai2024high}. Surfels are similar to the 3D Gaussian representation used in GS \cite{kerbl20233d}, with the key difference being that the 3D Gaussian is flattened into a 2D Gaussian. These 2D Gaussians can be oriented to align with the surface of a 3D object. 

The shape and location of the Gaussian can be parametrized by a covariance matrix $\mathbf{\Sigma} \in \mathbb{R}^{3 \times 3}$ and mean vector $\mathbf{x}_i \in \mathbb{R}^3$ respectively. The resulting 3D Gaussian can be expressed as  
\vspace{-1mm}
\begin{equation}
G(\mathbf{x}; \mathbf{x}_i, \mathbf{\Sigma}_i) = e^{ -\frac{1}{2} (\mathbf{x} - \mathbf{x}_i)^\top \mathbf{\Sigma}_i^{-1} (\mathbf{x} - \mathbf{x}_i) }.
\end{equation}
\vspace{-1mm}
\noindent Covariance matrices, by definition, are positive semi-definite and can be interpreted as describing the orientation of an ellipsoid. To enforce both of these properties, the covariance matrix can be decomposed as 
\vspace{-1mm}
\begin{equation}
    \mathbf{\Sigma} = (\mathbf{R}\mathbf{S})(\mathbf{R}\mathbf{S})^\top,
\end{equation}
\vspace{-1mm}
\noindent where $\mathbf{R} \in \mathbb{R}^{3 \times 3}$ is a rotation matrix and $\mathbf{S} \in \mathbb{R}^{3 \times 3}$ is a diagonal scaling matrix describing the scaling of the principal axes. $\mathbf{R}$ can be analytically expressed in terms of a quaternion $\mathbf{r} \in \mathbb{R}^4$ and the scaling matrix can be expressed as $\mathbf{S}=\operatorname{diag}(\mathbf{s})$, where $\mathbf{s} \in \mathbb{R}^3$ is the scaling vector. To flatten the 3D Gaussian to a 2D surfel, we set $\mathbf{s} = [s_1, s_2, 0]^\top$.

The resulting parametrization of the Gaussian kernels $\{\mathbf{x}_i, \mathbf{r}_i, \mathbf{s}_i, o_i, \mathcal{C}_i\}$ has five degrees of freedom: the mean $\mathbf{x}_i \in \mathbb{R}^3$ is the 3D location, $\mathbf{r}_i \in \mathbb{R}^4$ is the rotation expressed as a quaternion, $\mathbf{s} \in \mathbb{R}^3$ is scaling, $o_i \in \mathbb{R}$ is the opacity, and $\mathcal{C}_i \in \mathbb{R}^k$ are spherical harmonic coefficients.



% represented by unstructured 3D Gaussian, each described by a set of parameters $\{ \mathbf{x}_i, r_i, \mathbf{s}_i, o_i, C_i \}$, for each Gaussian $i$ with kernel position $\mathbf{x}_i \in \mathbb{R}^3$, quaternion rotation $\mathbf{r}_i \in \mathbb{R}^4$, scaling factors  $\mathbf{s}_i \in \mathbb{R}^3$, opacity $o_i \in \mathbb{R}$, and spherical harmonic coefficients $C_i \in \mathbb{R}^k$. Using covariance matrix $\Sigma_i$ as the product of scaling matrix $\mathbf{S}_i$ and rotation matrix $\mathbf{R}(\mathbf{r}_i)$, we set $\mathbf{s}_i = [\mathbf{s}_i^x, \mathbf{s}_i^y, 0]^\top$ to get the 3D Gaussian surfel distribution represented as: 


% \vspace{-4mm}
% \begin{equation}
% \begin{aligned}
%     \text{for} \quad \Sigma_i &= R(r_i) \mathbf{S}_i \mathbf{S}_i^\top R(r_i)^\top, \\
%      &= R(r_i) \text{Diag}\left[ (s_i^x)^2, (s_i^y)^2, 0 \right] R(r_i)^\top
% \end{aligned}  
% \end{equation}


% \paragraph{RGB Rendering}
\vspace{2mm}
\noindent
\textbf{Surfel Rasterization.} We follow prior works in volumetric rendering to rasterize surfel primitives to the image plane \cite{dai2024high, kerbl20233d, zwicker2001ewa}. The projection of a 3D Gaussian onto a 2D image plane can be approximated as a 2D Gaussian with mean $\mathbf{u}_i \in \mathbb{R}^2$ and covariance $\mathbf{\Sigma}_i' \in \mathbb{R}^{2 \times 2}$
\vspace{-1mm}
\begin{equation}
G'(\mathbf{u}; \mathbf{u}_i, \mathbf{\Sigma}'_i) = e^ {-\frac{1}{2} (\mathbf{u} - \mathbf{u}_i)^\top \mathbf{\Sigma}_i'^{-1} (\mathbf{u} - \mathbf{u}_i) }.
\end{equation}
\vspace{-1mm}
\noindent Given a view transformation $\mathbf{W} \in \mathbb{R}^{3\times 3}$ and the Jacobian of the affine approximation of the projective transformation $\mathbf{J} \in \mathbb{R}^{3\times 3}$, the covariance in image space is approximately 

\vspace{-1mm}
\begin{equation}
\mathbf{\Sigma}'_i = \left( \mathbf{J} \mathbf{W} \mathbf{\Sigma}_i \mathbf{W}^\top \mathbf{J}^\top \right) [: 2, : 2].
\end{equation}
\vspace{-3mm}

\noindent
\textbf{RGB Rendering.} The color $\tilde{\mathbf{C}}$ at a pixel $\mathbf{u}$ can be computed by sampling all $n$ surfels along the camera ray corresponding to the pixel. These samples can then be integrated to render a color using the alpha compositing equation

\vspace{-1mm}
\begin{equation}
\tilde{\mathbf{C}} = \sum_{i=0}^{n} T_i \alpha_i \mathbf{c}_i, \ \ T_i = \prod_{j=0}^{i-1} (1 - \alpha_j),  
\end{equation}
\vspace{-1mm}

\noindent where $\alpha_i = G'(\mathbf{u}; \mathbf{u}_i, \Sigma'_i) o_i$ is the alpha-blending weight and $\mathbf{c}_i$ is the color computed using $\mathcal{C}_i$ \cite{kerbl20233d}.


\vspace{2mm}
\noindent
\textbf{Surface Rendering.} The depth $\tilde{D}$ at a pixel can be estimated by computing the expected distance along the ray 

\vspace{-1mm}
\begin{equation}
    \tilde{D} = \frac{1}{1 - T_{n+1}} \sum_{i=0}^{n} T_i \alpha_i d_i(\mathbf{u}),
    \label{eq:render_depth}
\end{equation}
\vspace{-1mm}

\noindent where $d_i(\mathbf{u})$ is the distance of the $i$th Gaussian from the camera along pixel direction $u$. A key benefit of the surfel representation is that depth can be estimated precisely for any 2D surface in 3D space \cite{dai2024high}. The resulting intersection between the pixel ray and $i$th surfel can be estimated as  

\vspace{-2mm}
\begin{equation}
    d_i(\mathbf{u}) = d_i(\mathbf{u}_i) + (\mathbf{W} \mathbf{R}_i)[2, :] \mathbf{J}_{pr}^{-1} (\mathbf{u} - \mathbf{u}_i),
    \label{eq:surfel_depth}
\end{equation}
\vspace{-2mm}

\noindent where $\mathbf{J}_{pr}^{-1}$ is the Jacobian of inverse mapping, and $(\mathbf{W} \mathbf{R}_i)$ transforms the rotation matrix to the camera space. The surface normal $\tilde{\mathbf{N}}$ can be computed by replacing $d_i(\mathbf{u})$ in \cref{eq:render_depth} with the $z$ direction of the rotation matrix $\mathbf{R}_i[:, 2]$. 



