\vspace{2mm}
\noindent
\textbf{RGB Loss.} The RGB loss consists of two terms: data fidelity (L1) and perceptual similarity (SSIM)

% The L1 loss between the rendered pixel color $\tilde{\mathbf{C}}$ and the ground truth $\mathbf{C}_{gt}$ is weighted by an upscaled color variance mask $\mathbf{w}_{\text{color}}$ to account for varying importance across image regions. The total RGB loss is:

% \vspace{-1mm}
% \begin{equation}


\begin{equation}
\begin{split}
    \mathcal{L}_{\text{RGB}} 
    = (1 - \lambda_{\text{SSIM}}) \cdot \sum_{p \in \mathcal{P}}  w_p \| \tilde{\mathbf{C}}_p - \mathbf{C}_{p,gt} \|_1  \\
    + \lambda_{\text{SSIM}} \cdot (1 - \text{SSIM}(\tilde{\mathbf{C}}, \mathbf{C}_{gt})) \cdot \frac{1}{|\mathcal{P}|} \sum_{p \in \mathcal{P}} w_p.
\end{split}
\end{equation}


\vspace{-1mm}

\noindent $\mathbf{C}$ is the full image, $\mathbf{C}_p$ is the patch image, and
$\lambda_{\text{SSIM}}$ is a hyper-parameter weight. The L1 term is computed patch-wise, where each patch is weighted differently. The SSIM term is computed for the entire image and is weighted by the average weight across all image patches. 

\vspace{2mm}
\noindent
\textbf{Transient Loss.} The transient loss is the KL divergence between the normalized rendered transient and ground truth. 
% \sid{will fix this part once i define notation for transients}

\vspace{-3mm}
\begin{equation}
\mathcal{L}_{\text{transient}} = \sum_{p \in \mathcal{P}}(1-w_p) \cdot \text{KL}(i_p[t] \parallel i_{p, gt}[t]),
\end{equation}

\noindent where $i_p[t]$ is the transient corresponding to RGB patch $\mathcal{P}$.   
% \vspace{-1mm}


% \paragraph{Depth-Normal Regularization.} 

% where $N$ is the number of pixels.

\noindent
\paragraph{Combined Loss Function.} The three terms in the final loss function are the RGB loss $\mathcal{L}_{rgb}$, the LiDAR loss $\mathcal{L}_{lidar}$, and a depth-normal consistency regularization $\mathcal{L}_{reg}$ \cite{dai2024high}. Putting these terms together results in the combined loss 

\vspace{-1mm}
\begin{equation}
    \mathcal{L} =\mathcal{L}_{rgb} + \mathcal{L}_{lidar} + \mathcal{L}_{reg}.
\end{equation}
