    \centering
    \includegraphics[width=1.0\linewidth]{figures/reflection.pdf}
    % \vspace{-4mm}
    \caption{Comparisons of textual reflection generated by original Qwen2.5-VL-7B, our fine-tuned image reflector, and GPT-4o.}
    % \vspace{-2mm}
    \label{fig:reflection}
