\subsection{Dynamic Semantic-aware Transformer}
The Template Tokens $T_z\in \mathbb{R}^{n\times h_z\times w_z\times d_k}$ and Search Tokens $T_x\in \mathbb{R}^{1\times h_x\times w_x\times d_k}$ are inputs of Dynamic Semantic-aware Transformer, where $d_k$ is the dimensionality of the features. For simplicity and clarity, we present the details using single template, $T_z\in \mathbb{R}^{1\times h_z\times w_z \times d_k}$. We use a linear layer to transform the Search Tokens and Template Tokens into $({Q_x} \in \mathbb{R}^{h_x\times w_x \times d_k})$ and $({K_z} \in \mathbb{R}^{h_z \times w_z \times d_k})$. As shown in Figure \ref{overview}, we compute the Correlation Map ${C}$ between the $Q_x$ and $K_z$ as: 
\begin{equation}
C_{zx} = \frac{{Q_x{K_z^\top}}}{\sqrt{d_k}} \in \mathbb{R}^{h_x\times w_x\times h_z \times w_z \times l},
\end{equation}
where $C_{zx}$ captures the correlation scores between query from $x$ and key from $z$, corresponding to the $z$-to-$x$ similarity. $l$ represents the number of heads in the Transformer.

In the Correlation Map \( C_{zx} \), the modeling of the similarity relationship between points on \( Q_x \) and points on \( K_z \) can easily lead to ambiguity. We employ a dynamic perception-based prediction approach to calculate and fuse the similarity between semantically related points on \( K_z \) and \( Q_x \). 

\textbf{Dynamic Semantic Relevance Generator}. We first reshape $C_{zx} \in \mathbb{R}^{h_x\times w_x\times h_z \times w_z \times l}$ into $C_{zx} \in \mathbb{R}^{N_x\times N_z \times l}$, where $N_x = h_x\times w_x$ and $N_z = h_z \times w_z$. Then, We propose a Semantic Aware Modeling $\mathcal G=(\mathcal V,\mathcal E)$, where $\mathcal V=\{\vec c_{i}\mid \vec c_{i} \in C_{zx}, 1\leq i\leq N_z \}$ represents the set of nodes and the shape of $\vec c_{i}$ is $N_x\times1\times l$. In other words, we retrieve nodes along the second dimension of $C_{zx}$. $\mathcal E = \{(u, v) \mid \forall u \in \mathcal V, \forall v \in \mathcal V\}$ represents the set of Semantic Relevance. 
% To dynamically capture the semantic relevance between nodes, we design a Dynamic Graph Edge Generator. Specifically, we need to construct a dynamic adjacency matrix to store the relationships between nodes (Graph Edges). The semantic correlation between nodes is calculated through similarity, but to reduce the computational complexity, 
Specifically, we apply average pooling to the node features and we concatenate the vector $\vec{c_i}^{'}$ to form  $\vec{v}$:
\begin{equation}
\vec {c_i}^{'}=\frac{\sum_{j=0}^{N_x}\vec c_{j}}{N_x}, \vec c_{j} \in \mathbb R^{1\times 1\times l}\subseteq \vec{c}_i,
\end{equation}
\begin{equation}
    \vec{v} =[\vec {c_1}^{'},\vec {c_2}^{'},..., \vec {c_{N_z}}^{'}]\in\mathbb{R}^{N_z\times1\times l},
\end{equation}
where $[\cdot]$ represents concatenation.

Subsequently, we compute the similarity score $A$ between nodes via matrix multiplication:
 \begin{equation} A = \left(\vec v\right)^\top \left( \vec v\right),A\in \mathbb{R}^{N_z\times N_z \times l}. \end{equation}

After that, a tiny prediction network consisting of a multi-layer perceptron(MLP) and Log-Softmax function is utilized to predict the possibility that each Relevance will be retained and discarded:
\begin{equation}
\pi_{ij}=\mathrm{log}\frac{\mathrm{exp}\left(\mathrm{MLP}\left ( A_{ij}\right)\right)}{\sum^{N_z}_{k=1}\mathrm{exp}\left(\mathrm{MLP}\left ( A_{ik}\right)\right)}\in \mathbb{R}^{2}, 1\leq i,j \leq N_z.
\end{equation}
where $\pi_{ij,0}$ is the probability of retaining the Relevance $(i,j)$ and $\pi_{ij,1}$ is probability of removing it. 

Next, we apply the Gumbel-Softmax to produce the Dynamic Semantic Relevance $\mathcal E$, making the $\pi$ differentiable and retaining the most relevant connections:
% \begin{equation}
% G=\mathrm{Gumbel-Softmax}\left (\pi_{ij}\right)\in \{0,1\}\in \mathbb{R}^{N_z\times N_z}.
% \end{equation}
\begin{equation}
\label{equation:gumbel-softmax}
\mathcal E =\mathrm{Gumbel-Softmax}\left (\pi\right)\in \{0,1\}\in \mathbb{R}^{N_z\times N_z}.
\end{equation}
\textbf{Semantic Aware Modeling}. Therefore, we utilize the Semantic Aware Modeling to optimize the Correlation Map, as defined by the following formula:
\begin{equation}
% V = \hat{\Lambda}^{-\frac{1}{2}} \hat{A} \hat{\Lambda}^{-\frac{1}{2}} X^\top W,
% {C}' = \hat{\Lambda}^{-\frac{1}{2}} \hat{G} \hat{\Lambda}^{-\frac{1}{2}}{C}^\top W_v,
{C}'_{zx} = \Lambda^{-\frac{1}{2}} \hat{\mathcal E} \Lambda^{-\frac{1}{2}}C_{zx}^\top W_v \in \mathbb{R}^{N_x \times N_z \times l},
\end{equation}
where $\hat{\mathcal E} = \mathcal E + I$,  $I$ is the identity matrix, and $\Lambda_{ii} = \sum_j \mathcal E_{ij}$ is the degree matrix.

\textbf{Hybrid Attention}. The Semantic-aware Correlation Map is fed into an MLP and Gumbel-softmax to evaluate the importance of the Template Tokens. Less significant tokens are discarded based on $\mathcal{M} \in\{0, 1\}\in \mathbb{R}^{N_z\times N_z}$ to accelerate computation:
\begin{equation}
    \mathcal M =\mathrm{Gumbel-Softmax}\left (\mathrm{Log-Softmax}(\mathrm{MLP}(C'_{zx}))\right).
\end{equation}

Subsequently, we combine \( Q_z \), \( Q_x \), \( K_z \), \( K_x \), \( V_z \), \( V_x \), and \( {C}'_{zx} \) to compute the Hybrid Attention:
% \begin{equation}
% \label{C^{cat}}
%     C^{cat}=[\frac{Q_z{K}_z^\top}{\sqrt{d_k}},{C}'_{zx},\frac{Q_x{K}_z^\top}{\sqrt{d_k}},\frac{Q_x{K}_x^\top}{\sqrt{d_k}}] 
% \end{equation}
\begin{equation}
    \begin{aligned}
        &\mathrm{HAttention}(Q_x, K_x, V_x, K_z, V_z)=\\&[\mathrm{SelfAttention}(Q_z,  K_z, V_z),\mathrm{SelfAttention}(Q_x, K_x, V_x),\\ &\mathrm{CrossfAttention}(Q_x, K_z, V_z)].
    \end{aligned}
\end{equation}
The formula for Self-attention is as follows:
\begin{equation}
    \mathrm{SelfAttention}(Q,  K, V)=\mathrm{SoftMax}(\frac{Q{K}^\top}{\sqrt{d_k}})V.
\end{equation}
Cross-Attention can be calculated as follows:
\begin{equation}
    \mathrm{CrossAttention}(Q_x,  K_z, V_z)=\mathrm{SoftMax}(C^{'}_{zx}+C_{zx})V_z.
\end{equation}

% Then, we compute the Hybrid Attention by combining Eq.\ref{C^{cat}}:
% \begin{equation}
% \begin{aligned}
% &V^{cat} = \mathrm{Concat}(V_z, V_x),\\
%     \mathrm{HAttention}(&Q_x, K_x, V_x, K_z, V_z) =\mathrm{SoftMax}(C^{cat})V^{cat}\\
% \end{aligned}
% \end{equation}

Finally, we incorporated a Feedforward Neural Network (FFN) to enhance the model's fitting ability. The Dynamic Semantic-aware transformer can be summarized as follows:
\begin{equation}
    T^{''}_{xz} = T^{'}_{xz} +\text{FFN}(T^{'}_{xz}),
\end{equation}
\begin{equation}
\begin{aligned}
    T^{'}_{xz} &= &\text{HAttention}(Q_x, K_x, V_x, K_z, V_z)+T_{xz},
\end{aligned}
\end{equation}
where $T_{xz}$ represents the concatenation of $T_z$ and $T_x$.



