The proof is provided in the Appendix~\ref{append:proof_pro1}. Proposition~\ref{prop:prop1} indicates that problems~\eqref{eq:semikp} and~\eqref{eq:dynsemi} share the same optimal objective function value. Meanwhile, the optimal objective function value of the two-period transport problem~\eqref{eq:dynsemi} is independent of $\lambda$. Moreover, $v_t^*,g_t^*$ can be constructed using $\pi^*$.
% The above theorem shows that, given two unbalanced distributions \(p_0\) and \(p_1\), we can obtain the velocity field \(v\) and the growth function \(g\) by solving problem~\eqref{eq:semikp}. Specifically, the evolution of the density \(p_t\) is structured such that during the interval \([0,\lambda]\), it undergoes only growth or decay (driven solely by \(g\)), while during \((\lambda,1]\), it undergoes pure transport (driven solely by \(v\)), thereby evolving \(p_0\) into \(p_1\).

\paragraph{Building unbalanced dynamics.}Although we have identified a scheme in which \(p_0\) evolves into \(p_1\) through a two-period process governed separately by \(v_t\) and \(g_t\) respectively, this decoupling does not align with the behavior observed in biological systems, where transport and growth typically occur simultaneously. To address this, we next build an unbalanced dynamics based on the dynamic understanding discussed above that allows velocity and growth to jointly drive the state transition and mass growth while ensuring consistency with the target distribution. Specifically, given \(v_t\) $(t \in (\lambda,1])$, \(g_t\) $(t \in [0,\lambda])$ of the two-period process,
% \begin{equation}\label{eq:2period_dyn}
%     \partial_t p_t = g_t p_t, t \in [0,\lambda]; \quad \partial_t p_t = -\nabla \cdot (p_t v_t), t \in (\lambda,1],
% \end{equation}
we define the joint velocity $\tilde{v}_t$ and growth $\tilde{g}_t$ by
\begin{equation}\label{eq:reparam}
\begin{aligned}
&\tilde{v}_t(\x) = (1 - \lambda) \cdot v_{(1 - \lambda)t + \lambda}(\x), \\
&\tilde{g}_t(\x) = \lambda \cdot g_{\lambda t}\left(\psi_{\tilde{v},t}^{-1}(\x) \right),  
\end{aligned}
\end{equation}
where $t\in [0,1]$, and $\psi_{\tilde{v},t}$ is the flow generated by $\tilde{v}$, \ie, \(\psi_{\tilde{v},t}(\x_0) = \x_0 + \int_0^t \tilde{v}_s(\x) \mathrm{d}s\). 

\begin{thm}\label{thm:thm1}
Given the initial distribution $p_0$, denote the ending distribution of the two-period dynamics
\begin{equation}\label{eq:2period_dyn}
    \partial_t p_t = g_t p_t, t \in [0,\lambda]; \quad \partial_t p_t = -\nabla \cdot (p_t v_t), t \in (\lambda,1],
\end{equation}
as $p_1$, and denote the ending distribution of the joint dynamics starting from $p_0$
\begin{equation}
   \partial_t \tilde{p}_t = -\nabla \cdot (\tilde{p}_t \tilde{v}_t) + \tilde{g}_t \tilde{p}_t, \quad  t \in [0,1], \quad \tilde{p}_0 = p_0,
\end{equation}
as $\tilde{p}_1$, then it holds that \(\tilde{p}_1 = p_1\).
\end{thm}
