% \end{equation}


% where \(w_1(\x_0)\) denotes the value at \(\x_0\) of the vector \(\pi^{0\to1} \mathbf{1}_m\), \ie, the row-sum of \(\pi^{0\to1}\) associated with the source sample \(\x_0\). For simplicity we set $w_0(\x_0)=1$ for all $\x_0\sim p_0$.

