\subsection{Training Process}\label{sec:overalltrain}
% \textcolor{red}{Our ultimate goal is to generate data close to the real data distribution. Although flow matching is a powerful generative modeling framework, its learned velocity field is the expectation of the conditional velocity field, \ie,$v_\theta(x,t)=\mathbb{E}_{z|(x,t)}v_\theta(x,t|z)$, where $z=(x_0,x_1)$ is the entropic semi-relaxed OT plan in our setting. However, in practice, each integration step introduces an approximation error, and these local errors accumulate during the numerical ODE solving process, resulting in a global deviation from the true trajectory \cite{frans2025one}. To address this bias, we employ distribution fitting loss besides the flow matching loss in Eq.~\eqref{eq:loss_vgfm}, to improve performance further. Next, we introduce the distribution fitting loss and our training algorithm.}
Our ultimate goal is to generate data close to the real data distribution. The current learned velocity field of flow matching is the expectation of the conditional velocity field, \ie,$v_\theta(x,t)=\mathbb{E}_{z|(x,t)}v_\theta(x,t|z)$. In practice, since we use limited samples to learn the velocity field $v$, each numerical integration step introduces an approximation error, which can be accumulated during the numerical ODE solving process, resulting in a deviation from the true trajectory \cite{frans2025one}. To address this bias, we employ distribution fitting loss besides the flow matching loss in Eq.~\eqref{eq:loss_vgfm}, to improve performance further. Next, we introduce the distribution fitting loss and our training algorithm.


%\paragraph{Distribution fitting based on Wasserstein distance.}\label{sec:wasserstienloss}
% To achieve better performance, we also employ the Wasserstein distance between generated samples and observed samples as a part of the loss function. Specifically, denote $\mathcal{X}_t=\{\x_i^{(t)}\}_{i=1}^{N_t},t=0,1,\cdots, T-1$ as the samples  observed at different time points, and  $p_t\approx\sum_{i=1}^{N_t}\delta_{\x_i^{(t)}}$, define \( \phi_{v_\theta}:
% \mathbb{R}^d\times\mathcal{T}\to\mathbb{R}^{d|\mathcal{T}|}\) as the trajectory mapping fun of the neural network $v_\theta$ , which inputs a given starting point as the initial condition and outputs the observed particle coordinates at $\mathcal{T}$ following ODE dynamics, with $\mathcal{T}$ being a set of time indices. Starting with an initial set $\mathcal{X}_0$, $\phi_{v_\theta}$ predicts the subsequent sets of data points over the time indices in $\mathcal{T}$ . Specifically, the predicted sets are obtained by applying the Neural ODE function to $\mathcal{\mathcal{X}}_)$ and the full range of time indices from 1 to $T-1$, \ie, $\hat{\mathcal{X}}_1,\cdots,\hat{\mathcal{X}}_{T-1}=\phi_{v_\theta}(\mathcal{X}_0,\{1,\cdots,T-1\})$ . Similarly, we define $\phi_{g_\omega}$ as the particle weight mapping function of the neural network $g_\omega$, which inputs a given weight of particle $i$ as the initial condition and outputs the sampled weights at $\mathcal{T}$ following ODE dynamics. For simplicity of notation, we also use $w(A)$ to denote the set of weights of particles in set $A$.
To achieve better performance, we incorporate the Wasserstein distance between generated samples and observed samples as part of the loss function. Specifically, let \( \mathcal{X}_t = \{\x^i_{t}\}_{i=1}^{N_t} \) for \( t = 0, 1, \cdots, T-1 \) denote the observed samples at different time points, and denote \( p(\mathcal{X}_t) =  \sum_{i=1}^{N_t} \delta_{\x^i_{t}} \). We define \( \phi_{v_\theta}: \mathbb{R}^d \times \mathcal{T} \to \mathbb{R}^{d|\mathcal{T}|} \) as the trajectory mapping function parameterized by the neural network \( v_\theta \), which takes a given starting point as the initial condition and outputs particle coordinates at time indices \( \mathcal{T} \) according to ODE dynamics, where \( \mathcal{T} \) denotes a set of time steps. Given an initial set \( \mathcal{X}_0 \), the model \( \phi_{v_\theta} \) predicts particle positions at future time points in \( \mathcal{T} \). Specifically, the predicted samples are computed by applying the neural ODE to \( \mathcal{X}_0 \) over the time indices \( \{1, \cdots, T-1\} \), \ie, \( \hat{\mathcal{X}}_1, \cdots, \hat{\mathcal{X}}_{T-1} = \phi_{v_\theta}(\mathcal{X}_0, \{1, \cdots, T-1\}) \). Similarly, we define \( \phi_{g_\omega} \) as the particle weight mapping function parameterized by the neural network \( g_\omega \), which takes the initial weight of particle \( i \) as input and outputs the corresponding weight values at \( \mathcal{T} \) under ODE dynamics. For simplicity of notation, we use \( \hat{w}(\hat{\x}) \mbox{ for } \hat{\x}\in\hat{\mathcal{X}}_t \) to denote the weight generated by $\phi_{g_\omega}$ corresponding to the particles in set \( \hat{\mathcal{X}} \) which is generated by $\phi_{v_\theta}$ .
The distribution fitting loss is defined as the Wasserstein distance as 
\begin{equation}\label{eq:wloss}
    \mathcal{L}_{\mathrm{OT}}(\theta,\omega)=\sum_{t=1}^{T-1}\mathrm{\mathcal{W}_1}\left(\frac{1}{N_t}p(\mathcal{X}_t),\frac{1}{\sum_{\hat{\x}\in\hat{\mathcal{X}_t}} \hat{w}(\hat{\x})}p_{\hat{w}}(\hat{\mathcal{X}_t})\right),
    % \ \mathrm{where} \ w(\mathcal{X}_t)=\mathbf{1}_{N_t},
\end{equation}
where $p_{\hat{w}}(\hat{\mathcal{X}_t})=\sum_{\hat{\x}\in\hat{\mathcal{X}_t}} \hat{w}(\hat{\x})\delta_{\hat{\x}}$, ${\rm \mathcal{W}_1}$ is the 1-Wasserstein distance with Euclidean norm.
% \subsection{Training Loss}\label{sec:overalltrain}
\paragraph{Total loss and algorithm.}
Note that the matching loss can be easily generalized to multi-time snapshots by employing Eq.~\eqref{eq:loss_vgfm} 
among two consecutive snapshots $p_t$ and $p_{t+1}$. Combined with distribution fitting loss in Eq.~\eqref{eq:wloss}, we obtain the final loss
\begin{equation}\label{eq:finalloss}
\mathcal{L}(\theta,\omega)=\mathcal{L}_{\mathrm{VGFM}}(\theta,\omega)+\mathcal{L}_{\mathrm{OT}}(\theta,\omega)
\end{equation}
During training, we employ a parameter scheduling scheme in which we initially use $\mathcal{L}_{\rm VGFM}$ as a warm-up stage, before enabling both loss terms for joint training. This design provides a notable advantage: after the warm-up stage, \( v_\theta \) and \( g_\omega \) are well-initialized through conditional matching, which facilitates convergence when switching to $\mathcal{W}_1$-based training. The detailed algorithm is presented in Algorithm~\ref{algo:}. For further details on the warm-up procedure and parameter scheduling, please refer to Appendix~\ref{apdx:tau}.
% ; and (2) following the warm-up, \( v_\theta \) and \( g_\omega \) typically become nearly time-independent constants between two time points, allowing for larger ODE integration steps- or even one-step simulation. This significantly reduces the number of simulations required, resulting in improved training efficiency compared to other Neural ODE-based methods. 


\begin{algorithm}[t]
\caption{Training algorithm of joint velocity-growth flow matching}
\label{algo:}
\KwIn{Observed data $\mathcal{X}_0, \dots, \mathcal{X}_{T-1}$; warm-up epochs $M_1$; training epochs $M_2$}
\KwOut{Trained velocity field $v_\theta$ and growth function $g_\omega$}

Compute transport plans $\pi^{t \to t+1}$ for $t = 0, \dots, T-2$\;

\For{$i=1$ \KwTo $M_2$}{
    \For{$t_0 = 0$ \KwTo $T-2$}{
        Sample a batch $(i,j) \sim \pi^{t_0 \to t_0+1}$\;
        Sample $t \sim \mathcal{U}(0,1) + t_0$, and $\x_t \sim \mathcal{N}(t \x_1^j + (1 - t)\x_0^i, \sigma^2 I)$\;
        % Compute $v_t(x|z) = \x_1 - \x_0$, $g_t(x|z) = \log w_1(\x_0)$\;
        $\mathcal{L} \leftarrow \mathcal{L} + \left\|v_\theta(\x_t, t)-(\x_1^j-\x_0^i)\right\|^2 + \left| g_\omega(\x_t, t) - \log([\pi^{0\to 1}\mathbf{1}_m]_i)\right|^2$\;
        % \lambda_f \|v_\theta(\x,t) - v_t(x|z)\| + \lambda_g \|g_\omega(\x,t) - g_t(x|z)\|$\;
        \If{$i>M_1$}{
        $\hat{\mathcal{X}}_{t_0+1} \leftarrow \phi_{v_\theta}(\hat{\mathcal{X}}_{t_0}, t_0+1)$,\quad $\hat{w}_{t_0+1}(\hat{\mathcal{X}}_{t_0+1}) \leftarrow \phi_{g_\omega}(\hat{\mathcal{X}}_{t_0}, t_0+1)$\;
         $\mathcal{L} \leftarrow \mathcal{L}+\mathrm{\mathcal{W}_1}\left(\frac{1}{N_{t_0+1}}p(\mathcal{X}_{t_0+1}),\frac{1}{\sum_{\hat{\x}\in\hat{\mathcal{X}_t}} \hat{w}(\hat{\x})}p_{\hat{w}}(\hat{\mathcal{X}}_{t_0+1})\right)$\;
        }

    }
    Update $\theta,\omega$ using $\mathcal{L}$
}

\end{algorithm}

\section{Methodology}
\label{sec:methods}

\subsection{Preliminary}
\label{sec:preliminary}

Video-text retrieval is a task that involves retrieving relevant videos based on a given text query, or conversely, retrieving appropriate text descriptions for a video. Consistent with previous approaches~\cite{huang2023vop,cao-etal-2024-rap,yang2024dgl,jin2024mv}, we utilize the CLIP model, pre-trained on image-text data, as our backbone. 

To process a given video, we first sample a sequence of frame images uniformly, which are then input into the CLIP vision encoder to extract image features $v^{\rm img}$. These features are then aggregated through temporal average pooling to get video features $v^{\rm vid}$.
For a given video caption, it is passed through the CLIP text encoder to extract video caption features $t^{\rm vid}$. Then, we compute the cross-modal contrastive loss~\cite{oord2018representation}, which functions as a video-level alignment term, maximizing the video-level similarity ${\rm Sim}^{\rm vid}$ between matched pairs:
\begin{gather}
{\rm Sim}^{\rm vid}_{ij}=t^{{\rm vid}^T}_{i}v^{\rm vid}_{j}, \label{eq:video_sim} \\
\mathcal{L}_{t2v} ({\rm Sim}^{\rm vid}) = \frac{1}{B} \sum_{i=1}^{B} {\rm log} \frac{{\rm exp}({\rm Sim}^{\rm vid}_{ii})/\tau)}{\sum_{j=1}^B {\rm exp}({\rm Sim}^{\rm vid}_{ij})/\tau)}, \\
\mathcal{L}_{v2t} ({\rm Sim}^{\rm vid}) = \frac{1}{B} \sum_{i=1}^{B} {\rm log} \frac{{\rm exp}({\rm Sim}^{\rm vid}_{ii})/\tau)}{\sum_{j=1}^B {\rm exp}({\rm Sim}^{\rm vid}_{ji})/\tau)}, \\
    \mathcal{L}_{A} ({\rm Sim}^{\rm vid}) = - \frac{1}{2}[\mathcal{L}_{t2v} ({\rm Sim}^{\rm vid}) + \mathcal{L}_{v2t} ({\rm Sim}^{\rm vid})], \label{loss:align}
\end{gather}
\noindent where $B$ is the batch size, $\tau$ is the temperature parameter. 

