%         \left( \sum_{(i, j) \in \pi} d(T_i, \hat T_j)^q \right)^{\frac{1}{q}}
% \end{equation}
\begin{equation}
    s_t = \texttt{DTW}(T, \hat{T})
\end{equation}
%where $\pi$ is an alignment path (a sequence of pairs of points belonging to the two trajectories minimizing the sum of distances), $\mathcal{A}({T}, {\hat T})$  is the set of all admissible paths (all paths following an increasing temporal ordering) and $d$ is a distance measure (we use the Euclidean distance).
Where $\mathbf{\texttt{DTW}}$ returns the cost of aligning $T$ to $\hat{T}$ according to the DTW algorithm\footnote{We used this implementation: \url{https://pypi.org/project/fastdtw/}.}.
%\todo{Aggiungere formulazione}

\noindent
\textit{Heatmap}
Differently from previous functions, this approach explicitly considers the probability values predicted by the model at each location.% (Fig. \ref{fig:scoring}(d)).
Specifically, we evaluate the likelihood of a ground truth eye fixation $T_i$ obtained by the device under the predicted heatmap $\hat Q_i$, which can be computed as:

\begin{equation}
    P(T_i|\hat Q) = \hat Q_i(T_i^x, T_i^y)
\end{equation}

\noindent
where $T_i^x$ and $T_i^y$ are the coordinates of the trajectory point $T_i = [T_i^x, T_i^y]$. The score associated to the predicted trajectory $\hat T$ is computed as the sum of the likelihoods of each trajectory point, considering the predicted heatmap $\hat Q$:

\begin{equation}
    s_t = \sum_{i=F/2+1}^F P(T_{t-F+i}|\hat Q).
\end{equation}

\noindent
\textit{Entropy}
This is the only method which does not require ground truth gaze for computation. We consider this measure as a way to check whether mistakes are systematically characterized by uncertain gaze predictions. %(Fig. \ref{fig:scoring}(c)).
 In this case, the score $s_t$ is set as the mean entropy of all predicted heatmaps for a given trajectory \( \hat{T} \). The entropy \( H \) of a single heatmap \( \hat{Q} \) is given by:
\begin{equation}
s_t = -\frac{1}{F/2}\sum_{i={ F/2}+1}^{F} \sum_{x,y} \hat Q_{t-F+i}^{(x,y)} \log_2(\hat Q_{t-F+i}^{(x,y)})
\end{equation}
$Q_j^{(x,y)}$ is the value at coordinates $(x,y)$ of heatmap $Q_j$.

