\textbf{Forward propagation}:
\begin{equation}
    Attention(Q,K,V) = softmax(\frac{QK^{T}}{\sqrt{d_k}})V
\end{equation}

% zk:以下的公式符号可能需要讲解，如D_θ，Dθ_{Q/K/V}, DW_{Q/K/V}, D_{Q/K/V}, H_{qkv}, G_{qkv}, x, X是什么，或者说我们按照哪篇tutorial的setting进行计算？

\textbf{Backward propagation}:
\begin{equation}
    D\theta =vec(DW)=\delta\otimes x
\end{equation}
Here, $\otimes$ denotes the Kronecker product, and $vec()$ represents the vectorization operation. Thus, the gradient of $\theta_{qkv}$ can be written as:

\begin{equation}
    D\theta_{qkv} = \begin{bmatrix} \mathbf{vec(DW_Q)} \\ \mathbf{vec(DW_K)} \\ \mathbf{vec(DW_V)} \end{bmatrix} \\
 = \begin{bmatrix} \mathbf{\delta}_q \\ \mathbf{\delta}_k \\ \mathbf{\delta}_v \end{bmatrix} \otimes x
\end{equation}
Let $\delta_{qkv}$
 $= \begin{bmatrix} \mathbf{\delta}_q \\ \mathbf{\delta}_k \\ \mathbf{\delta}_v \end{bmatrix} $. Then, the Hessian matrix $H_{qkv}$ can be estimates by:
\begin{equation}
\begin{aligned}
    H_{qkv} = E(D\theta_{qkv} {D\theta_{qkv}}^T)=E(\delta_{qkv}\delta_{qkv}^T\otimes x_{qkv}x_{qkv}^T) \\
    \approx E(\delta_{qkv}\delta_{qkv}^T) \otimes E(x_{qkv}x_{qkv}^T) = \Delta_{qkv} \otimes X_{qkv}
\end{aligned}
\end{equation}

Also, $H_o = \Delta_o \otimes X_o$. Thus, the iHVP of the attention layer can be estimated as follows: 

\begin{equation}
\begin{aligned}
H_{att}^{-1}v_{att} = 
\begin{bmatrix}\mathbf {H_{qkv}^{-1}v_{qkv}} \\ \mathbf{H_o^{-1}v_o}  \end{bmatrix}
= \begin{bmatrix} \mathbf{(\Delta_{qkv} \otimes X_{qkv})^{-1}v_{qkv}} \\ \mathbf{(\Delta_{o} \otimes X_o)^{-1}v_o} \end{bmatrix} \\
= \begin{bmatrix} \mathbf{(\Delta_{qkv}^{-1} \otimes X_{qkv}^{-1})v_{qkv}} \\ \mathbf{(\Delta_{o}^{-1} \otimes X_o^{-1})v_o} \end{bmatrix}
= \begin{bmatrix} \mathbf{vec(\Delta_{qkv}^{-1} V_{qkv} X_{qkv}^{-1})} \\ \mathbf{vec(\Delta_{o}^{-1} V_o X_o^{-1})} \end{bmatrix}
\end{aligned}
\end{equation}
% \begin{center}
% $(G+\lambda I)^{-1}v = vec(Q_x^T[(Q_xVQ_{qkv}^T)\varnothing unvec(diag^{-1}(\Lambda+\lambda I))]Q_{qkv})$
% \end{center}
% $\varnothing$denotes element-wise division, and $unvec()$ represents the inverse operation of $vec()$, $Q_{qkv}$ and $Q_x$ are the eigenvalue decompositions of $E_{qkv}$ and $X$, respectively. $E_{qkv} = Q_{qkv}\Lambda_{qkv}Q_{qkv}^T$, $X = Q_x\Lambda_{x}Q_x^T$, $\Lambda_{ii} = E[((Q_{qkv} \otimes Q_S)D\theta)_i^2]$

where $v_{att}$, $v_{qkv}$, $v_{o}$ represent the gradient of reference dataset $D_r$ on parameters $\theta_{att}$, $\theta_{qkv}$, $\theta_{o}$, respectively. Thus, the influence score of attention layers can be written as:  $I_{\theta_{att}} = -\nabla L(\theta_{att}, z)H_{att}^{-1}v_{att}$.


To avoid the excessive memory usage of validation set gradients, we apply the Johnson-Lindenstrauss Lemma to reduce the dimensionality of both the iHVP computation results and the training data gradients $\nabla L(\theta,z)$.

\section{Methodology}
\label{sec:methodology}
This section details \textbf{LittleBit}. We describe its factorized architecture with multi-scale compensation (\cref{sec:little_bit_arch}), the Dual-SVID initialization for stable QAT (\cref{sec:dual_svid}), and Residual Compensation for enhanced fidelity (\cref{sec:residual_compensation}). These components are optimized via QAT (details in \cref{sec:experiments}).

\subsection{LittleBit Architecture}
\label{sec:little_bit_arch}
The LittleBit architecture, depicted in \cref{fig:littlebit_arch}, redesigns linear layers for extreme compression (\eg 0.1 BPW) by synergistically combining low-rank factorization and binarization. LittleBit first leverages the observed low-rank structure in LLM weights~\citep{svdllmv1_2025} to approximate the weight matrix $\mathbf{W} \in \mathbb{R}^{d_\mathrm{out} \times d_\mathrm{in}}$ as:
\begin{equation}
\label{eq:svd}
\mathbf{W} \approx \mathbf{U} \mathbf{V}^\top \quad (\mathbf{U} \in \mathbb{R}^{d_\mathrm{out} \times r}, \mathbf{V} \in \mathbb{R}^{d_\mathrm{in} \times r}, r \ll \min(d_\mathrm{in}, d_\mathrm{out}))
\end{equation}
This factorization-based approach is chosen over other structural compression methods, such as pruning, due to its superior robustness in extreme compression regimes. As demonstrated in our comparative analysis against methods like Wanda (\cref{appendix:pruning_vs_svd}), SVD-based compression maintains model integrity far more effectively at high compression ratios, providing a more stable foundation for our ultra low-bit quantization.
The resulting factors $\mathbf{U}$ and $\mathbf{V}$ are then binarized:
\begin{equation}
\label{eq:uv_sign}
\mathbf{U}_\mathrm{sign} = \mathrm{sign}(\mathbf{U}), \quad \mathbf{V}_\mathrm{sign} = \mathrm{sign}(\mathbf{V}) \in \{-1, +1\}
\end{equation}
To compensate for the significant information loss incurred by binarization~\citep{survey2024}, LittleBit incorporates learnable FP16 scales. Beyond standard row ($\mathbf{h}$) and column ($\mathbf{g}$) scaling~\citep{pbllm2023,onebit2024,arbllm2025}, it introduces an \textit{additional latent} scale ($\boldell \in \mathbb{R}^r$). This latent scale is designed to address the factorization structure by learning the relative importance of each of the $r$ latent dimensions, which correspond to the columns of the binarized factors $\mathbf{U}_\mathrm{sign}$ and $\mathbf{V}_\mathrm{sign}$:
\begin{equation}
\label{eq:ghl_scales_combined}
\mathbf{h} \in \mathbb{R}^{d_\mathrm{out}}, \quad \mathbf{g} \in \mathbb{R}^{d_\mathrm{in}}, \quad \boldell \in \mathbb{R}^{r}
\end{equation}
The primary effective weight, $\widehat{\mathbf{W}}_\mathrm{pri}$, is implicitly constructed from these components:
\begin{equation}
\label{eq:w_primary_hat}
\widehat{\mathbf{W}}_\mathrm{pri} = \mathrm{diag}(\mathbf{h}) \mathbf{U}_\mathrm{sign} \mathrm{diag}(\boldell) \mathbf{V}_\mathrm{sign}^\top \mathrm{diag}(\mathbf{g})
\end{equation}
Instead of storing or optimizing $\widehat{\mathbf{W}}_\mathrm{pri}$ directly, LittleBit learns latent full-precision factors $\mathbf{U}$ and $\mathbf{V}$, which are binarized during the forward pass using \cref{eq:uv_sign}, along with the FP16 scales $\mathbf{h}, \mathbf{g}, \boldell$. This factorized representation enables efficient computation during the forward pass.

\paragraph{Proposition 1}
Let $\mathbf{X} \in \mathbb{R}^{\mathrm{seq} \times d_\mathrm{in}}$ be the input matrix. The forward computation $\mathbf{Y} = \mathbf{X}{\widehat{\mathbf{W}}_\mathrm{pri}}^\top$ using the primary approximation (\cref{eq:w_primary_hat}) can be efficiently computed as:
\begin{equation}
\label{eq:proposition1}
\mathbf{Y} = (( ( (\mathbf{X} \odot \mathbf{g}) \mathbf{V}_\mathrm{sign} ) \odot \boldell ) \mathbf{U}_\mathrm{sign}^\top ) \odot \mathbf{h}
\end{equation}
where $\odot$ denotes element-wise multiplication with broadcasting.

This decomposition (\cref{eq:proposition1}) replaces a large high precision General Matrix Multiply (GEMM) operation with two smaller binary matrix multiplications and element-wise scaling operations, offering computational advantages and reducing memory requirements. The effective bits per weight (BPW) is determined by the storage cost of these learnable parameters relative to the original matrix size (see \cref{appendix:average_bit} for more details).

\subsection{Dual-SVID Initialization}
\label{sec:dual_svid}
Naively initialing the highly constrained LittleBit structure can lead to unstable QAT. To circumvent this, we propose \textbf{Dual-SVID}, an SVD-based initialization method designed to provide a starting point where the initial effective weight $\widehat{\mathbf{W}}_{\mathrm{pri}, 0}$ closely approximates $\mathbf{W}$. Dual-SVID aims to preserve essential sign and magnitude information from the optimal low-rank SVD factors (obtained from $\mathbf{W} \approx \mathbf{U}' {\mathbf{V}'}^\top$, then truncated) and map this information to the learnable LittleBit parameters ($\mathbf{U}_\mathrm{sign}, \mathbf{V}_\mathrm{sign}, \mathbf{h}, \mathbf{g}, \boldell$). The process involves: (1) Obtaining $\mathbf{U}', \mathbf{V}'$ via a truncated SVD. (2) Setting initial binary factors based on signs (\cref{eq:sign_init_concise}). (3) Decomposing the magnitudes $|\mathbf{U}'| \in \mathbb{R}^{d_\mathrm{out} \times r}$ and $|\mathbf{V}'| \in \mathbb{R}^{d_\mathrm{in} \times r}$. To initialize the scales, we perform a rank-1 SVD (or equivalent rank-1 approximation) on each of these magnitude matrices separately. For $|\mathbf{U}'|$, its best rank-1 approximation can be written as $\mathbf{s}_{U,0} (\boldell_{u,0})^\top$, where $\mathbf{s}_{U,0} \in \mathbb{R}^{d_\mathrm{out}}$ becomes the initial row scale $\mathbf{h}_0$, and $\boldell_{u,0} \in \mathbb{R}^r$ is a component contributing to the latent scale. Similarly, for $|\mathbf{V}'|$, its rank-1 approximation $\mathbf{s}_{V,0} (\boldell_{v,0})^\top$ provides the initial column scale $\mathbf{g}_0 = \mathbf{s}_{V,0} \in \mathbb{R}^{d_\mathrm{in}}$ and another latent scale component $\boldell_{v,0} \in \mathbb{R}^r$. These steps effectively disentangle multi-dimensional magnitude variations and allow us to estimate initial row ($\mathbf{h}_0$), column ($\mathbf{g}_0$), and the final latent scale ($\boldell_0 = \boldell_{u,0} \odot \boldell_{v,0}$ by element-wise product), as shown in (\cref{eq:scale_init_rank1_concise,eq:latent_scale_init_concise_0}):
\begin{gather}
\label{eq:sign_init_concise}
\mathbf{U}_{\mathrm{sign}, 0} = \mathrm{sign}(\mathbf{U}'), \quad \mathbf{V}_{\mathrm{sign}, 0} = \mathrm{sign}(\mathbf{V}') \\
\label{eq:scale_init_rank1_concise}
|\mathbf{U}'| \approx \mathbf{h}_0 (\boldell_{u, 0})^\top, \quad |\mathbf{V}'| \approx \mathbf{g}_0 (\boldell_{v, 0})^\top \\
\label{eq:latent_scale_init_concise_0}
\boldell_0 = \boldell_{u, 0} \odot \boldell_{v, 0}
\end{gather}
