\section{Method}
\label{sec:method}

\begin{figure*}[htbp]
    \centering
    \includegraphics[width=\linewidth]{figures/model.pdf}
    % \caption{Model.\ph{7}}
    \caption{\textbf{The Overall Pipeline of \model.} Given a 3D point cloud as input, we predict entity mask proposals and generate text descriptions for each entity. Then different views of the scene are randomly masked and we replace the masked point features with learnable embeddings. A 3D UNet then extracts per-point features. Guided by the entity masks, cross-view point-to-entity contrastive learning is conducted to enforce cross-view consistency and distinguishment across different entities. Then we merge the point features from two views and align the feature dimension of points with text features extracted by CLIP with a VL-Adapter. Finally, entity-to-language contrastive learning is performed for open-vocabulary 3D scene understanding.}
    \vspace{-3mm}
    \label{fig:model}
\end{figure*}

In this section, we elaborate on the proposed masked point-entity contrastive learning framework for open-vocabulary 3D scene understanding. The overall architecture is presented in~\cref{fig:model}. In essence, our model aims to learn 3D point features $\mF_P\in\sR^{N\times D}$ that maintain 3D information of 3D scenes, a vision-language (VL-) adapter $\mathrm{Proj}_{\text{VL}}(\cdot)$ that maps these 3D features into the semantic space which is aligned with language features $\mF_{T}$ extracted from a pre-trained text encoder. The input of our framework mainly consists of three components: \begin{enumerate*}[label=\arabic*)]
    \item 3D scene point cloud $\pcd = \left( \mP, \mC \right)$, where $\mP \in \sR^{N \times 3}$ and $\mC \in \sR^{N \times 3}$ represents spatial coordinates and colors of the points.
    \item $K$ 3D entity mask proposals obtained with off-the-shelf methods which are merged into $\mM \in \{ \texttt{BG}, 1, \cdots, K\}^{N}$ where \texttt{BG} denotes the background.
    \item Text descriptions $\mT = \{t_i\}_{i=1}^{N_T}$ including captions and referrals, which could be generated for each entity proposal by template-based methods or foundation models.
\end{enumerate*} %

\subsection{Point-to-Entity Alignment}
\label{method:e2e} %
\paragraph{Cross-view Feature Extraction} We start by extracting separate point features from different augmented views of the scene for contrastive representation learning. Specifically, given a 3D point cloud $\pcd$, two distinct augmented views $\pcd_{u}$ and $\pcd_{v}$ are generated, along with their transformed entity masks $\mM_{u}$ and $\mM_{v}$. Following the practice of previous works~\cite{xie2022simmim, he2022masked, wu2023masked}, we divide the unioned set of point clouds into non-overlapping grids based on the original spatial locations. Then two sets of non-overlapping grid masks $\mG_{u}$ and $\mG_{v}$ are randomly generated and applied to the corresponding
views. We use the same mask token embedding $\vt\in\sR^{3}$ for the color of all masked points. We then feed the masked point clouds of separate views into the 3D U-Net encoder $\bm{\mathcal{E}}_{\text{pcd}}$ to extract per-point embeddings:
\begin{equation} \label{eq:extract_point_feats}
    \begin{aligned}
        \mF_{l} = \bm{\mathcal{E}}_{\text{pcd}}((1 - \mG_{l})\pcd_{l} + \mG_{l}\mT_{l}), && l\in\{u, v\},
    \end{aligned}
\end{equation}
where $\mT_{u}$ and $\mT_{v}$ are the expansions of the learnable embedding vector to fit the dimension with point cloud across different views, respectively.

\vspace{-3mm}
\paragraph{Point-to-Entity Contrastive Learning} After obtaining the point features from two views, we perform point-to-entity contrastive learning to incorporate entity information into our learned scene representations. Specifically, we calculate the cosine similarity matrix $\vs^{u \to v}$ between all pairs of matched points by computing the similarities of point $i$ from view $u$ to points in view $v$ belonging to entities and background separately. Let $\cossim(\vf_1,\vf_2) = \frac{\vf_1^T\cdot \vf_2}{\|\vf_1\|\cdot\|\vf_2\|}$ to denote the cosine similarity function, for points $\mE_k^v = \{j \mid \mM_v[j] = e_k\}$ that belong to entity $e_k$ in view $v$, we have:
\begin{equation}
    \vs^{u \to v}_{i,e_k} = \frac{1}{|\mE_k|} \sum_{j\in \mE_k} s^{u \to v}_{i,j} = \frac{1}{|\mE_k|} \sum_{j\in\mE_k} \cossim(\mF_u^i, \mF_v^j).
\end{equation}
Meanwhile, for the remaining $L$ background points $\{b_1, b_2, \cdots, b_L\}$ in view $v$, we compute the similarity between point $i$ to the each $b_j$ in view $v$ with cosine similarity $\vs_{i,b_j}^{u\to v} = \cossim(\mF_u^i, \mF_v^{b_j})$. After these calculations, we obtain the entity-aware point similarities $\vs_i^{u\to v}$ for point $i$ by
\begin{equation}
    \scalebox{0.95}{$\vs_i^{u\to v} = \mathrm{Concat}\left(\vs_{i,e_1}^{u\to v}, \cdots, \vs_{i, e_K}^{u\to v}, \vs_{i,b_1}^{u\to v}, \cdots, \vs_{i,b_L}^{u\to v}\right)$},
\end{equation}
and add point-entity contrastive supervision depending on whether point $i$ belongs to an entity or background in view $u$. If point $i$ belongs to an entity, then we have
\begin{equation}
    \ell_{i}^{u \to v} = -\log \frac{\exp(\vs^{u \to v}_{i,\bar{e}} / \tau)}{\sum_r \exp(\vs^{u \to v}_{i,r} / \tau)}, 
\end{equation} where $\bar{e}$ is the entity in view $v$ that point $i$ belongs to. If point $i$ belongs to the background, then we use
\begin{equation}
    \ell_{i}^{u \to v} = -\log \frac{\exp(\vs^{u \to v}_{i,\bar{b}} / \tau)}{\sum_r \exp(\vs^{u \to v}_{i,r} / \tau)}, 
\end{equation}
to align point $i$ with its corresponding background point $\bar{b}$ in view $v$ with a temperature factor $\tau$. We can similarly compute the similarity from view $v$ to $u$ and obtain the final point-entity contrastive loss:
\begin{equation} \label{loss:e2e}
\begin{aligned}
    \mathcal{L}_\text{p2e} = \frac{1}{2}\left(\frac{1}{N}\sum_{i}\ell_i^{u\to v} + \frac{1}{N}\sum_{j}\ell_j^{v\to u}\right).
\end{aligned}
\end{equation}

\subsection{Entity-to-Language Alignment}
\label{method:e2l}
To achieve open-vocabulary 3D scene understanding, we align the 3D point features with language features. First, we merge the 3D point features from both views to generate the final point features $\mF_\gP$. Next, we feed the text descriptions of 3D entities to a frozen text encoder $\bm{\mathcal{E}}_{\text{txt}}$ to extract language features $\mF_{T}$. Then we perform entity-to-language contrastive learning to align the 3D point features with their corresponding language features.

\vspace{-3mm}
\paragraph{Point Features Merging} In~\cref{method:e2e}, we extract point features $\mF_{u}$ and $\mF_{v}$ for different augmented views of the input point cloud. To fully utilize the advantages of both views' features and further align with language features, we merge $\mF_{u}$ and $\mF_{v}$ to obtain point features $\mF_\gP$ by taking the mean feature of matched points in the two views. We then feed the merged features to the VL-adapter $\mathrm{Proj}_{\text{VL}}(\cdot)$ to align the dimension of point and language features:
\begin{equation}
\begin{aligned}
    \mF_\gP = \mathrm{Mean}(\mF_u, \mF_v), && \mF_{\text{VL}} = \mathrm{Proj}_{\text{VL}}(\mF_\gP).
\end{aligned}
% \vspace{-3mm}
\end{equation}

\vspace{-3mm}
\paragraph{\textbf{Language Feature Extraction}}
Given various text descriptions $\mT$, \eg, object captions $\mT_\text{cap}$ and referrals $\mT_\text{ref}$ of different 3D entities in the scene, we random sample $N_\text{T}$ descriptions and extract their embeddings using the pre-trained CLIP text encoder $\bm{\mathcal{E}}_{\text{txt}}$ of CLIP~\cite{radford2021learning}:
\begin{equation}
\mF_{T} = \bm{\mathcal{E}}_{\text{txt}}(\mT) \in \sR^{N_\text{T}\times D}.
% \vspace{-3mm}
\end{equation}

\vspace{-3mm}
\paragraph{Entity-to-Language Contrastive Learning}
After obtaining the adapted 3D point features $\mF_{\text{VL}}$ and entity text description features $\mF_{T}$, we conduct entity-to-language contrastive learning to align their representations. 
% Analogous to \cref{method:e2e}, we employ a point-discriminative loss that imposes no penalty on points within the same entity, while contrasting points from different entities. 
Analogous to~\cref{method:e2e}, we employ a point-discriminative loss to enforce consistency among matched point-language pairs, while contrasting unmatched pairs.
Specifically, given the language features $\mF_{T}$ and adapted vision features $\mF_{\text{VL}}$, we first compute the cosine similarity matrix $\vs^{t\to e}$. For language description $i$, we compute its similarity to all points in an entity $e_k$ by
\begin{equation}
\begin{aligned}
    \vs^{t \to e}_{i,e_k}= \frac{1}{|\mE_k|} \sum_{j\in \mE_k}\cossim(\mF_T^i, \mF_{\text{VL}}^j), 
\end{aligned}
\end{equation}
where $\mE_k = \{j | \mM[j] = e_k\}$ denotes the set of points that belongs to entity $e_k$. We concatenate text-to-entity similarities $\vs_i^{t\to e}$ between text $i$ and all entity features derived from $\mF_{\text{VL}}$ by
\begin{equation}
\begin{aligned}
    \vs_i^{t \to e} = \mathrm{Concat}(\vs^{t \to p}_{i,e_1}, \vs^{t \to p}_{i,e_2}, \cdots, \vs^{t \to e}_{i,e_K}). 
\end{aligned}
\end{equation}

Let $\bar{e}$ denote the entity that aligns with text description $i$, we compute the text-to-entity contrastive loss with temperature factor $\tau$ as:
\begin{equation}
\begin{aligned}
    \ell^{t \to e}_i = -\log \frac{\exp(\vs^{t \to e}_{i,\bar{e}} / \tau)}{\sum_k \exp(\vs^{t \to e}_{i, k} / \tau)}.
\end{aligned}
\end{equation} 

Similarly, we can compute the entity-to-text similarity $\vs^{e \to t}$. However, in contrast to the direct symmetry between point-to-entity and entity-to-point alignment in~\cref{method:e2e}, the entity-to-text loss $\ell^{e\to t}$ needs adjustments as different descriptions can refer to the same object entity in the scene and thus disable the application of the cross-entropy loss. Therefore, we replace the loss with a binary cross-entropy loss when applying the entity-to-language supervision:

\begin{equation}
\scalebox{0.9}{%
$
\begin{aligned}
\ell^{e \to t}_{k} = - \frac{1}{N_{T}}\sum_{t\in\mT} & \left[ \mathbb{1}(t\in\{\bar{t}\})\log\left(\sigma\left(s^{e \to t}_{k,t}\right)\right) + \right.
\\
  & \left.(1-\mathbb{1}\left(t\in\{\bar{t}\}\right))\log\left(1 - \sigma\left(s^{e \to t}_{k,t}\right)\right)\right],
\end{aligned}
$
}
\end{equation}
where $\{\bar{t}\}$ is the set of text descriptions that describes enitity $k$, $\mathbb{1}(\cdot)$ is an indicator function testing if a text $t$ is within the descriptive texts $\{\bar{t}\}$ of the entity $k$. Finally, we combine the two-side contrast for entity-to-language alignment with:

\begin{equation} \label{loss:e2l}
\begin{aligned}
    \mathcal{L}_\text{e2l} = \alpha \frac{1}{N_\text{t}}\sum_{i=1}^{N_\text{t}}\ell^{t \to e}_i + \beta \frac{1}{K}\sum_{k=1}^{K}\ell^{e \to t}_{k},
\end{aligned}
\end{equation}
where factors $\alpha$ and $\beta$ serve to balance the scale of cross-entropy loss and binary cross-entropy loss.

\subsection{Model Learning}
\label{method:training_obj}

\paragraph{Training Data} We obtain training data following the data curation pipeline from SceneVerse~\cite{jia2024sceneverse}. Specifically, we use an off-the-shelf 3D instance segmentation model~\cite{zhu2024unifying} to generate entity mask proposals on ScanNet and generate referential and descriptive text of objects with the help of scene graphs and 2D foundation models~\cite{openai2023gpt4v} for fair comparisons with existing methods. We also leverage the generated paired \ac{3dvl} data from other real 3D scene datasets, including 3RScan~\cite{wald2019rio}, HM3D~\cite{ramakrishnan2021habitat} and MultiScan~\cite{mao2022multiscan} in SceneVerse as additional training data.

\vspace{-3mm}
\paragraph{Learning Objectives} Our training objective is fully contrastive-based. We combine both the point-to-entity alignment in~\cref{loss:e2e} and the entity-to-language alignment in~\cref{loss:e2l}, enabling the end-to-end training of the 3D encoder $\bm{\mathcal{E}}_{\text{pcd}}$ and the VL-adapter $\mathrm{Proj}_{\text{VL}}(\cdot)$, leading to a final loss function as:
\begin{equation}
\begin{aligned}
    \mathcal{L}_{\text{overall}} = \mathcal{L}_\text{p2e} + \mathcal{L}_\text{e2l}.
\end{aligned}
\vspace{-1mm}
\end{equation}
\paragraph{Implementation Details} For our default model, we adopt sparse-convolution based UNet (SPUNet)~\cite{graham20183d, choy20194d} as the 3D encoder and CLIP~\cite{radford2021learning} as the text encoder. The VL-adapter is implemented with a two-layer MLP. During training, we only update the parameters of the 3D encoder and VL-adapter and keep the text encoder frozen. We provide more training details in the \supp.
