\section{Sampling diverse attacks with GFlowNet fine-tuning}

\subsection{Preliminaries}
The target LLM, denoted $p_\phi$, samples a text response $\rvy$ for a given prompt $\rvx$ with probability $p_\phi(\rvy\mid \rvx)$. The goal of red-teaming an LLM is to identify prompts $\rvx$ that elicit toxic responses from the target LLM. A binary toxicity classifier, denoted as $p_\psi$, is used to quantify the effectiveness of an attack prompt. Specifically, the effectiveness of a prompt $\rvx$ is measured by the likelihood of the response $\rvy\sim p_\phi(\rvy\mid\rvx)$ being classified as toxic by the classifier: $p_\psi(c=1\mid\rvx, \rvy)$, where $c\in\{0,1\}$ is a binary variable denoting toxicity. Moreover, for the attack to be effective, the prompt $\rvx$ should appear natural, as unnatural prompts (with high perplexity under some prior) are easy to defend against with simple filters~\citep{perplexity-filtering}. 

Red-teaming can often be a time-consuming process if done manually as the space of prompts is quite large. \citet{perez-etal-2022-red, curosity-red-teaming} formulate red-teaming as an RL problem, to automate the discovery of these prompts. This involves training a LM as a policy $p_\theta$, parameterized by $\theta$, to generate prompts that maximize the expected reward (as measured by the toxicity of the response generated by the target LLM):
\begin{equation}
    \maximize_{\theta} \mathbb{E}_{\rvx~\sim p_\theta(\rvx), y\sim p_\phi(\rvy\mid\rvx)}\left[p_\psi(c=1\mid\rvx, \rvy)\right] -\lambda \infdiv{p_\theta}{p_\texttt{ref} },
\label{eq:rl}
\end{equation}
where the KL divergence term, weighted by a hyperparameter $\lambda>0$, encourages the policy $p_\theta$ to remain close to an initial pretrained LM $p_\texttt{ref}$, penalizing the generation of prompts $\rvx$ that are far from natural language text. However, most RL algorithms are not suitable for discovering diverse prompts since they generally concentrate most of probability mass of the policy $p_\theta$ on actions with highest reward, often resulting in a deterministic policy that generates a single prompt~\citep{bengio2021flow}. While~\citet{curosity-red-teaming} propose adding a novelty-based reward term along with entropy bonus~\citep{entropy-bonus} as a regularization to encourage the policy to generate diverse prompts, empirically we find that it is challenging to find an optimal trade-off between diversity and toxicity rate even with the regularization. In the context of red-teaming, identifying diverse \emph{and} effective attack prompts is critical to ensure that the target LLM is sufficiently safety-tuned for a broad range of scenarios which might be encountered when the model is deployed in the wild. 

\begin{figure}[t]
\vspace{-0.1in}
\begin{algorithm}[H]
\captionof{algorithm}{Training a language model with GFlowNet and smoothing with MLE}
\label{algo:re-train}
\begin{spacing}{0.89}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Pretrained language model $p_\theta$, toxicity classifier $p_\psi$, target LLM $p_\phi$, learning rate $\alpha, \eta$, batch size $m_1, m_2$, threshold $r_1, r_2$, reward temperature $\beta,\gamma$, the number of samples $k$.
    \STATE $p_\texttt{ref}\leftarrow \texttt{deepcopy}(p_\theta)$, $\mathcal{B}\leftarrow \emptyset$, $\mathcal{D}\leftarrow \emptyset$,  $\ell \leftarrow 0$.
    \WHILE {not converged \quad\quad {{\textcolor{blue}{// \texttt{Stage 1:\ GFlowNet fine-tuning}}}} \hspace*{-2.8in}} 
    \FOR{$i=1, \ldots, m_1$}
    \STATE Uniformly randomly sample behavior policy $b\in\{\text{tempered policy},\ \text{replay buffer}\}$.
    \IF{$b=\text{tempered policy}$}
    \STATE Uniformly randomly set $\tau\leftarrow 1.0$ or $\tau \leftarrow \texttt{Uniform}(0.5, 2.0)$.
    \STATE Sample $\rvx$ from $p_\theta(\rvx)$ with temperature $\tau$ and
    sample $\rvy^{(i)}$ from $p_\phi(\rvy|\rvx)$ for $i=1,\ldots, k$.
    \STATE $\log R_1(\rvx) \leftarrow \frac{1}{\beta\cdot k} \sum_{i=1}^k \log p_\psi(c=1| \rvx, \rvy^{(i)}), \log R_2(\rvx) \leftarrow \frac{1}{\gamma}\log p_\texttt{ref}(\rvx)$.
    \STATE Add $\rvx$ to the offline dataset $\gD$ \textbf{if} $\beta\log R_1(\rvx) \geq r_1$ and $\gamma\log R_2(\rvx)\geq r_2$.
    \STATE Add $(\rvx, \beta\log R_1(\rvx), \gamma\log R_2(\rvx))$ to the replay buffer $\gB$.
    \ELSE
    \STATE Sample $(\rvx, \beta\log R_1(\rvx), \gamma\log R_2(\rvx))$ from the replay buffer $\gB$.
    \ENDIF
    \STATE Compute the loss $\ell \leftarrow \ell + \mathcal{L}(\rvx;\theta)/m_1$ with \autoref{eq:reward} and \autoref{eq:tb}.
    \ENDFOR
    \STATE Update $p_\theta$ with gradient descent: $\theta \leftarrow \theta -\alpha \frac{\partial \ell}{\partial \theta}$ and initialize the loss $\ell \leftarrow 0$.
    \ENDWHILE
    \STATE Re-initialize the policy: $p_\theta \leftarrow p_\texttt{ref}$.
    \WHILE {not converged \quad\quad {{\textcolor{blue}{// \texttt{Stage 2:\ MLE smoothing}}}} \hspace*{-2.25in}}
    \STATE Sample a mini-batch $S\subset \gD$ of size $m_2$  and compute loss: $\ell \leftarrow \frac{1}{m_2}\sum_{\rvx \in S}  [-\log p_\theta (\rvx)]$.
    \STATE Update $\theta$ with gradient descent: $\theta \leftarrow \theta -\eta \frac{\partial \ell}{\partial \theta}$.
    \ENDWHILE
    \STATE \textbf{Output:} Policy $p_\theta$
\end{algorithmic}
\end{spacing}
\end{algorithm}
