\section{Methodology}



Given an original training dataset \( T = \{(x_i^{t}, y_i^{t})\}_{i=1}^{N_t} \) with \( N_t \) samples, where each \( x_i^{t} \) and \( y_i^{t} \) represent the \( i \)-th image and its corresponding class label, we employ Fo-Mixup to generate a diverse set of synthetic forgery images. Additionally, we use standard data augmentation to produce augmented versions of the real images. This process yields a synthesized dataset \( S = \{(x_i^{s}, y_i^{s})\}_{i=1}^{N_s} \) comprising \( N_s \) samples, where \( x_i^{s} \) and \( y_i^{s} \) denote the \( i \)-th synthetic image and its class label, respectively. Using both the synthesized forgery images and the augmented real images, we then regularize our model to maintain consistency across the original \( T \) and synthesized \( S \) domains for both real and forgery classes. 




\subsection{Forgery Mixup Augmentation}

% image
% background, hair color,

The amplitude spectrum of an image retains low-level statistics, such as forgery artifacts, color, style information, and sensor artifacts, while the phase spectrum includes high-level semantic content \cite{xu2021fourier,piotrowski1982demonstration,oppenheim1981importance}. In deepfake detection, training the detector without specific considerations can cause the model to over-rely on domain-specific details (such as hair color, background, texture, and style) encoded in the amplitude spectrum \cite{luo2021generalizing}. Our experiments show that this overemphasis on dominant frequency components can lead to overfitting, where the model performs well on training data but poorly on out-of-distribution forgeries.


 To address these challenges, we introduce the Fo-Mixup augmentation to modulate the dominant frequency components within the amplitude spectrum of different forgery images. Fo-Mixup exposes our forgery detector to more variations in the dominant frequency components of the amplitude spectrum during training. This exposure encourages the detector to attend to a broader range of frequency bands, thereby promoting the learning of more generalizable features and reducing overfitting.


\begin{algorithm}[t]
\caption{Fo-Mixup Augmentation}
\label{alg:fomixup}
\begin{algorithmic}[1]
\footnotesize
\setstretch{1} % Adjust the factor as needed

\Statex \textbf{Inputs:} Input forgery images $x_i$ and $x_j$, interpolation hyperparameter $\xi$, total number of angular segments $T$, total number of clusters $k$, top number of clusters $t$, constant distance $r$, constant angle $\theta$ from the horizontal axis, a normal distribution $p_{\mathcal{A}}$, pre-trained forgery \mbox{detector}.
\Statex \textbf{Outputs:} Augmented forgery image $x_{ij}$\\

$[\mathcal{A}(x_i), \mathcal{P}(x_i)] \leftarrow \mathcal{F}(x_i)$ \Comment{ FFT for $x_i$}\\



$[\mathcal{A}(x_j), \mathcal{P}(x_j)] \leftarrow \mathcal{F}(x_j)$ \Comment{ FFT for $x_j$}\\


$\{\mathcal{A}_{\text{seg}_1},\ldots,\mathcal{A}_{\text{seg}_T} \} \leftarrow \operatorname{Partition}(\mathcal{A}(x_i,r,\theta))$  \Comment{ Partition $\mathcal{A}(x_i)$ into $T$ angular segments with constant distance $r$ and angle $\theta$}\\

$ \{\mu_{\text{seg}_1}, \ldots, \mu_{\text{seg}_T}\} \leftarrow \{\frac{1}{{N}_{\text{seg}_z}} \sum_{\mathcal{A}_{\text{seg}_z}} \log(1+|\mathcal{A}_{\text{seg}_z}|)\}^{T}_{z=1}$\newline\Comment{Mean log-scaled spectrum}\\%



 $\{\mu_1, \ldots, \mu_k\} \leftarrow \operatorname{K-means}(\{\mu_{\text{seg}_1}, \ldots, \mu_{\text{seg}_T}\})$\Comment{Clustering}\\

%$\{\mathcal{B}_{1},\ldots,\mathcal{B}_k\} = \{\text{indices}_{\mu_1}, \ldots, \text{indices}_{\mu_k}\}$ \Comment{Masks Generation}\\

$\{\mathcal{B}_{1},\ldots,\mathcal{B}_k\} \leftarrow \{ \text{indices}_{\mu_z}\}^{k}_{z=1}$ \Comment{Binary masks}\\




 $\{\mathcal{A}_{\mu_1}, \ldots, \mathcal{A}_{\mu_k}\}\leftarrow \{\mathcal{A}(x_i)\otimes\mathcal{B}_{z}\}^{k}_{z=1}$ \Comment{Filtering}\\

 $\{x_{{\mu_1}}, \ldots, x_{{\mu_k}}\}\leftarrow \{\mathcal{F}^{-1}[\mathcal{\mathcal{A}}_{\mu_z},\mathcal{P}(x_i)]\}^{k}_{z=1}$ \Comment{Filtered images}\\




$\{x_{{\mu_{s1}}}, \ldots, x_{{\mu_{st}}}\} \leftarrow \operatorname{OHEM}(\{x_{{\mu_1}}, \ldots, x_{{\mu_k}}\})$ \Comment{Apply OHEM \cite{shrivastava2016training} to the filtered images using our pre-trained forgery detector}\\

$\{\mathcal{B}_{1},\ldots,\mathcal{B}_t\} \leftarrow \{ \text{indices}_{\mu_{sz}}\}^{t}_{z=1}$ \Comment{Keep top $t$ clusters, selected by OHEM in step 9. These clusters correspond to the highest loss values.}\\


$\mathcal{B} \leftarrow \operatorname{RandomSelect}(\mathcal{B}_{1},\ldots,\mathcal{B}_t)$ \Comment{Random selection}\\

$\mathcal{\hat{A}}(x_{ij})\leftarrow\mathcal{A}(x_i)\otimes\mathcal{B} +\left[(1-\xi) \mathcal{A}(x_i) +\xi \mathcal{A}(x_j)\right]\otimes(1-\mathcal{B})$ \\


$x_{ij}\leftarrow \mathcal{F}^{-1}\left[p_{\mathcal{A}}\otimes\mathcal{\hat{A}}(x_{ij}),\mathcal{P}(x_i)\right]$\Comment{Reconstruct image}
\State \textbf{Return  $x_{ij}$} \Comment{Augmented forgery image}
\end{algorithmic}\label{alg:fomixup}
\end{algorithm}

\begin{figure*}[t] 
\centering
\hspace{2cm} % Add a gap of 1 inch on the left side
\includegraphics[width=0.99\textwidth]{maincameracroppedcompressedlast.pdf}
\caption{Overview of the proposed FreqDebias framework. First, Fo-Mixup diversifies the forgery class across frequency spectra by transforming $x^t$ into $x^s$, while preserving the spatial structure of tampered regions. Then, the network is jointly regularized at local and global levels to enforce consistent representation learning. For the real class, the same process is applied using standard augmentation.}
\label{framework}
\end{figure*}

Given an input forgery image $x_i$, we apply the fast Fourier transformation $\mathcal{F}(x_i)$ on each RGB channel to compute its amplitude $\mathcal{A}(x_i)$ and phase $\mathcal{P}(x_i)$ components. Fo-Mixup initiates with the identification of the key frequency components within the input forgery image. 





To achieve this, we partition the amplitude spectrum into angular segments, with radial and angular components divided into intervals \( r \in [i_r \Delta r, (i_r+1) \Delta r] \) and \( \theta \in [i_\theta \Delta\theta, (i_\theta+1) \Delta\theta] \). The radial component measures distance from the origin, while the angular component defines orientation in the frequency domain. The indices \( i_r \) and \( i_\theta \) denote discrete steps, and the step sizes \( \Delta r \) and \( \Delta \theta \) determine the segmentation resolution. For each segment, we compute the mean logarithmic-scaled spectrum denoted as $\mu_{\text{seg}}$, as the average of $\log(1+|\mathcal{A}_{seg}|)$ values within the segment, where $\mathcal{A}_{seg}$ is the segment’s amplitude spectrum.



Next, we apply the K-means clustering algorithm \cite{macqueen1967some} to all angular segments using the mean spectrum $\mu_{\text{seg}}$ of all angular segments. The $k$ cluster indices are then employed to construct $k$ binary masks, which are subsequently used to filter the input image into $k$ distinct filtered images. We feed the filtered images into our detector and arrange the classification losses in descending order, following the Online Hard Example Mining (OHEM) \cite{shrivastava2016training}. Finally, we randomly select one of the top $t$ binary masks (denoted as $\mathcal{B}$) as the ones associated with the highest loss values. To integrate the key frequency components of different forgery images, the selected binary mask $\mathcal{B}$ is applied to the amplitude component (shown in Fig. \ref{framework}). These operations are formulated as follows:
\begin{multline}\label{eq.4}
\mathcal{\hat{A}}(x_{ij})=\mathcal{A}(x_i)\otimes\mathcal{B}  
\\ +\left[(1-\xi) \mathcal{A}(x_i) +\xi \mathcal{A}(x_j)\right]\otimes(1-\mathcal{B}),
\end{multline}
\noindent where $x_i$ and $x_j$ are the randomly selected forgery inputs, and $\xi$ denotes the hyperparameter that adjusts the proportion of inputs. Also, $\otimes$ denotes element-wise multiplication. To expose our model in CR to more forgery artifacts variations in the dominant frequency component, we also perturb the amplitude spectrum as $p_{\mathcal{A}}\otimes\mathcal{\hat{A}}(x_{ij})$, where $p_{\mathcal{A}}$ is a normal distribution $ \mathcal{N}(1,0)$. Finally, the inverse Fourier transform reconstructs the newly stylized image using the phase component of the original input $\mathcal{P}(x_i)$ and the integrated amplitude spectrum $\mathcal{\hat{A}}(x_{ij})$ as follows:
\begin{equation}\label{eq.5}
\begin{aligned}
x_{ij}= \mathcal{F}^{-1}\left[\left(p_{\mathcal{A}}\otimes\mathcal{\hat{A}}(x_{ij})\right)* e^{-i*\mathcal{P}(x_i)(u,v)}\right],
\end{aligned}
\end{equation}
\noindent where $u$ and $v$ represent coordinates in frequency domain. The generated image $x_{ij}$ retains the semantic content of $x_i$ with diversified dominant frequency components. This expands the detector focus across frequency bands. The Fo-Mixup augmentation is outlined in Algorithm \ref{alg:fomixup}.  



\vspace{1mm}
\noindent\textbf{Confidence Sampling.}
Augmented samples with high prediction entropy (i.e., low confidence) hinder generalization performance. To address this, we filter out unreliable samples from the pool of augmented data using Shannon entropy, defined as \( E_{x_{ij}} = -\mathbf{p}(x_{ij}) \log \left(\mathbf{p}(x_{ij})\right) \), where \( x_{ij} \) is the augmented sample and \( \mathbf{p}(x_{ij}) \) denotes the model’s output probability for that sample. After calculating the entropy for each prediction, we rank the samples in ascending order and select the top \( \lambda \)  percent of high-confidence samples.









\subsection{Consistency Regularization}


Our model consists of a feature extraction module with multiple stages, represented as $\Psi = \psi_M \circ \dots \circ \psi_2 \circ \psi_1$, where $M$ denotes the number of stages in the network. Since each layer captures concepts at different abstraction levels \cite{zhang2022attributable}, from low-level textures to high-level semantics, we introduce a feature alignment module $\omega_i$ after each stage to capture regularized semantic abstractions progressively across the network. We express these as $F_i = \omega_i \circ \psi_i(x) \circ \dots \circ \psi_1(x)$, where $i \in {1, \dots, M}$. The feature alignment module, which includes convolutional and residual blocks similar to those in ResNet \cite{he2016deep}, ensures that each auxiliary branch undergoes the same number of down-sampling operations as the backbone, supporting a fine-to-coarse feature transformation. With the feature alignment modules in place, the backbone is trained and its class posterior distributions for the predictions of the synthesized $(x^{s}, y) \in {S} $ and training images $(x^{t}, y) \in {T} $ are regularized as follows:
\begin{multline}\label{eq.10}
    L_{{cls}} = \mathcal{L}_{{CE}} \Bigl( \sigma\bigl(\alpha_{f} (x^s)\bigr), y \Bigr) + \mathcal{L}_{{CE}} \Bigl( \sigma\bigl(\alpha_{f} (x^t)\bigr), y \Bigr) \\
    + {D_{KL}} \Bigl( \sigma\bigl(\alpha_{f}(x^s); \tau\bigr), \sigma\bigl(\alpha_{f}(x^t); \tau\bigr) \Bigr),
\end{multline}
\noindent where $\mathcal{L}_{{CE}}$ indicates the standard cross-entropy (CE) loss function, $D_{{KL}}$ denotes the Kullback-Leibler (KL) divergence, and $\alpha_{f} (x)$ is the final prediction of our model. Also, ${\sigma}(\alpha(x) ; \tau)$ denotes the Softmax operation with temperature $\tau$. When $\tau=1$, it would be a normal Softmax operation, expressed as ${\sigma}(\alpha_i (x))$. 

\vspace{1mm}
\noindent\textbf{Attention Consistency Regularization.} With the synthesized forgery samples covering a wider range of dominant frequency components, we first regularize our detector using local consistency to identify consistent visual cues, regardless of dominant frequency variations. To achieve this, we compute CAMs \cite{sun2020fixing,zhou2016learning} on the feature map \( F_M \in \mathbb{R}^{c \times h \times w} \) at the final stage of our backbone, where \( c \), \( h \), and \( w \) represent the number of channels, height, and width, respectively. CAMs offer valuable interpretability by highlighting the critical regions in an image that are relevant for detecting forgeries. The proposed Fo-Mixup augmentation is designed to maintain the spatial location of tampered regions consistently between the input image \( x^t \) and the synthesized forgery \( x^s \), preserving critical information for detection. By enforcing CAM consistency, we ensure that our forgery detector remains focused on the discriminative regions, making it less susceptible to domain-specific noise or artifacts that could otherwise mislead its predictions. For consistency supervision at the attention level, we calculate CAMs using a global average pooling (GAP) layer followed by a fully connected (FC) layer with weights \( W \in \mathbb{R}^{c \times n} \), where \( n \), the number of classes, is two. The FC layer is trained using the CE loss function, \( L_{CAM} \), to distinguish between forgery and real samples. The CE loss is defined as \( L_{CAM} = -\sum_{i=1}^{n} y_i \log(\hat{y}_i) \), where \( y_i \) is the true label and \( \hat{y}_i \) is the predicted probability for class \( i \). The classifier weights \( W \) are convolved with the feature map \( F_M \) to compute the CAMs as follows:
\begin{equation}\label{eq.12a}
M = W^\top F_M,
\end{equation}
\noindent where \( M \in \mathbb{R}^{n \times h \times w} \). This process ensures that the CAMs can effectively highlight the most discriminative regions for the forgery classification. The CAMs are then normalized within the class region so that the highly valued features are solely assigned to the class region. For class-wise normalization, the CAMs are average pooled and clustered into different clusters using the K-means algorithm \cite{macqueen1967some}. The first cluster (formulated as ${Mask^{high}}$) highlights the class region and the remaining ones would be discarded. Then, the obtained category region with $Mask^{high}$ is further normalized by instance normalization \cite{ulyanov2017improved} to have a standard distribution. These operations are summarized as follows:
\begin{equation}\label{eq.13}
	{M^{cn}}= (M \otimes {Mask^{high}})\gamma + \beta,
\end{equation}
\noindent where ${M^{cn}}$ and ${Mask^{high}}$ denote the class-wise normalized CAMs and the highlighted class region at the last layer of our backbone. $\gamma$ and $\beta$ are learnable affine parameters in the instance normalization. After all, we match the refined CAMs (i.e., ${M^{cn}}$) between the synthesized and original training domains by the Jensen-Shannon Divergence (JSD) as follows:
\begin{equation}\label{eq.14}
	{L_{att}}= D_{JS}\Bigl({\sigma}\bigl({M^{cn}}(x^{s}); \tau\bigr) ,{\sigma}\bigl({M^{cn}}(x^{t}); \tau\bigr)\Bigr),
\end{equation}
\noindent where ${M^{cn}}(x^{s})$ and ${M^{cn}}(x^{t})$ are the class-wise normalized CAMs for the synthesized and training images.


\noindent\textbf{Hyperspherical Consistency Regularization.} 
Recent research demonstrates the effectiveness of hyperspherical latent spaces over Euclidean spaces in modeling the complex geometric structure of facial feature representations \cite{wang2022towards,kirchhof2022non,hasnat2017mises,li2021spherical}. To leverage this, we introduce a vMF classifier, implemented as a mixture model with two vMF distributions, to statistically model facial feature representations on the hyperspherical space for CR. To capture a global view of the embedding space for consistent geometric learning, we leverage hierarchical feature maps from different stages of the backbone network to construct our vMF classifier. To achieve this, feature maps from these stages are concatenated and resized as $\boldsymbol{F}_{cat} = \operatorname{Conv}\left(\operatorname{Concat}([F_1,....,F_M])\right)$, where $\operatorname{Conv}$ denotes the $1\times1$ convolutional layer that reduces the channel dimension of the concatenated feature maps. Given a normalized facial feature representation $\tilde{ \boldsymbol{F}}_{cat}=\boldsymbol{F}_{cat} /\left\|\boldsymbol{F}_{cat}\right\|_2$, the probability density function (PDF) for $i$-th class is formulated as follows:
\begin{gather}
p\left(\tilde{ \boldsymbol{F}}_{cat} \mid {\kappa_i}, \tilde{ \boldsymbol{\mu}}_i\right)=\mathcal{C}_d\left(\kappa_{i}\right) \exp \left({{\kappa_i} \cdot \tilde{ \boldsymbol{F}}_{cat} \tilde{ \boldsymbol{\mu}}_i^{\top}}\right),  \label{eq.15} \\
\mathcal{C}_d\left({\kappa_{i}}\right)=\frac{\kappa_i^{\frac{d}{2}-1}}{(2 \pi)^{\frac{d}{2}} \cdot I_{\frac{d}{2}-1}\left({\kappa_i}\right)}, \label{eq.16}
\end{gather}
\noindent where $\tilde{ \boldsymbol{F}}_{cat} \in \mathbb{S}^{d-1}$ is the d-dimensional unit vector, and ${\kappa_i} \in \mathbb{R}_{\geq0}$ and $\tilde{ \boldsymbol{\mu}}_i \in \mathbb{S}^{d-1}$ are trainable compactness parameter and orientation vector of the vMF classifier for $i$-th class. Also, $I_\beta (\kappa)$ is the modified Bessel function of the first kind at order $\beta$ and $C_d({\kappa})$ is a normalization constant. Given the PDF in Eq. \ref{eq.15}, and the posterior probability, the vMF classifier is trained using CE loss as below:
\begin{equation}
    	{{L}_{{cls\_sphere}}} = \mathcal{L}_{CE}\left(p(y_i \mid \tilde{\boldsymbol{F}}_{{cat}})\right), \label{eq.17}
\end{equation}
\begin{equation}
	\hfill p\left(y_i \mid \tilde{\boldsymbol{F}}_{{cat}}\right) = \frac{n_i \cdot p\left(\tilde{\boldsymbol{F}}_{{cat}} \mid {\kappa_i}, \tilde{\boldsymbol{\mu}}_i\right)}{\sum_{j=1}^2 n_j \cdot p\left(\tilde{\boldsymbol{F}}_{{cat}} \mid {\kappa_j}, \tilde{\boldsymbol{\mu}}_j\right)}, \label{eq.18}
\end{equation}
\noindent where $n_i$ indicates the cardinality of class $i$, and $p\left(y_i \mid \tilde{ \boldsymbol{F}}_{cat}\right)$ denotes the probability of $\boldsymbol{F}_{cat}$ being associated with class $i$. To enforce the geometric CR, the Distribution Matching Score ($\mathrm{DMS}$) is formulated  as follows:


\begin{equation}
\mathrm{DMS} = \left. 1 \middle/ \left( 1 + D_{\mathrm{KL}}\big( p(\tilde{ \boldsymbol{F}}_{cat}^{s} \mid \kappa_s, \tilde{ \boldsymbol{\mu}}_s),\; p(\tilde{ \boldsymbol{F}}_{cat}^{t} \mid \kappa_t, \tilde{ \boldsymbol{\mu}}_t) \big) \right) \right.
\end{equation}



\noindent where $0<\mathrm{DMS}<1$ represents the overlap between the synthesized $S$ and training domains $T$. When two domains are highly overlapped, $\mathrm{DMS} \to 1$. Finally, to enhance CR, we maximize the $\mathrm{DMS}$ between the synthesized $S$ and training domains $T$ in vMF optimization as below:
\begin{equation} \label{eq.20}
{L}_{sphere}=\mathbb{E}\left[1-\mathrm{DMS}(\boldsymbol{F}_{cat}^{s},\boldsymbol{F}_{cat}^{t})\right],
\end{equation} 

\noindent where $\mathbb{E}$ is the average function.

\vspace{1mm}
\noindent\textbf{Overall Loss.}
The overall objective function in our training optimization boils down to five loss functions as follows:
\begin{multline}\label{eq.21}
L_{total}= {L_{cls}} + \eta  {L_{CAM}}   \\ +\delta{L_{att}} +\mu{{L}_{cls\_sphere}} +\rho{L}_{sphere},
\end{multline} 
\noindent where $\eta$, $\delta$, $\mu$, and $\rho$ are hyperparameters that balance the impact of different loss functions. Having trained our proposed model end-to-end, we remove all introduced auxiliary classifiers during testing, incurring no additional computational cost compared to the baseline backbone.

\section{Methodology}\label{sec: method}

\subsection{Preliminaries}
\noindent\myparagraph{Diffusion Model.}
Text-to-video generation models usually utilize the diffusion paradigm, which gradually transforms noise $\epsilon$ into a video $x_0$. Originally, denoising was conducted directly within the pixel space \cite{DDIM, DDPM, DPM}; however, due to significant computational overheads, recent methods predominantly employ latent space \cite{LDM, Videopoet, magictime, animatediff}. The optimization process is defined:
\begin{equation}
\label{eq: original_loss_function}
\mathcal{L}_{a}=\mathbb{E}_{x_0, t, y, \epsilon}\left[\left\|\epsilon-\epsilon_\theta\left(x_0, t, \tau_\theta(y)\right)\right\|_2^2\right],
\end{equation}
where $y$ is text condition, $\epsilon$ is sampled from a standard normal distribution (\eg, $\epsilon \sim \mathcal{N}(0, 1)$), and $\tau_\theta(\cdot)$ is the text encoder. By replacing $x_0$ with $\mathcal{E}\left(x_0\right)$, the latent diffusion is derived, which is used by ConsisID.

\noindent\myparagraph{Diffusion Transformer.}
The DiT-based video generation model shows significant potential in simulating the physical world \cite{SORA, cogvideox, allegro}. Despite being a novel architecture, research on controllable generation has been limited, and current methods \cite{tora, pulid, Camera_DiT, movie_gen} largely resemble U-Net based approaches \cite{controlnet, t2iadapter, textual_inversion}. However, no study has yet examined why this approach works with DiT. Drawing from prior analyses of Diffusion and Transformer from a frequency domain perspective \cite{rethinking_DiT, ViT, HAT, U-ViT, U-DiTs, Freeu}, we conclude that: \textbf{(1)} Low-frequency (\eg, shallow-layer) features are essential for pixel-level prediction tasks in diffusion models, which helps facilitate model training; \textbf{(2)} Transformers have limited perception for high-frequency information, which is important for controllable generation. Based on these, we decouple ID features into high- and low-frequency parts and inject them into specific locations, achieving effective identity-preserving text-to-video generation.

\subsection{ConsisID: Keep Your Identity Consistent}
The overview is illustrated in Figure \ref{fig: model_pipeline}. Given a reference image, the global facial extractor and local facial extractor inject both high- and low-frequency facial information into model, which then generates identity-preserving videos with the assistance of the consistency training strategy.

\subsubsection{Low-frequency View: Global Facial Extractor}
In light of \textit{Finding 1}, enhancing low-level (\eg, shallow, low-frequency) features accelerates model convergence. To easily adapt a pre-trained model for the IPT2V task, the most direct approach is concatenating the reference face with the noise input latent \cite{svd}. However, the reference face contains both high-frequency details (\eg, eye and lip textures) and low-frequency information (\eg, facial proportions and contours). From \textit{Finding 2}, prematurely injecting high-frequency information into the Transformer is inefficient and may hinder the model's processing of low-frequency information, as the Transformer focuses primarily on low-frequency features. In addition, feeding the reference face directly into the model could introduce irrelevant noise such as lighting and shadows. To mitigate this, we extract facial key points, convert them to an RGB image, and then concatenate it with the reference image, as shown in Figure \ref{fig: model_pipeline}. This strategy focuses the model's attention on the low-frequency signals in the face, while minimizing the impact of extraneous features. We found that when this component is discarded, the model is difficult to convergen. The objective function is changed to:
{\small
\begin{equation}
\label{eq: global_loss_function}
\mathcal{L}_{b}=\mathbb{E}_{x_0, t, y, f, \epsilon}\left[\left\|\epsilon-\epsilon_\theta\left(x_0, t, \tau_\theta(y), \psi_\theta(f)\right)\right\|_2^2\right],
\end{equation}
}where $\psi_\theta(\cdot)$ is a variational autoencoder, $f$ represents the reference image, we ignore key points here for simplicity.

\subsubsection{High-frequency View: Local Facial Extractor}
In light of \textit{Finding 2}, we recognize that Transformers have limited sensitivity to high-frequency information. It can be concluded that relying solely on global facial extractor is insufficient for IPT2V generation, as global facial features lack of high-frequency information. So we use a face recognition backbone \cite{arcface} to extract high-frequency features, as these are invariant to non-ID attributes (\eg, expression, posture, and shape). We refer to these features as intrinsic identity features (\eg, high-frequency), since age and makeup do not alter an individual’s core identity. Following \cite{UniPortrait}, we utilize the penultimate layer of the backbone, rather than its output, as it retains more spatial information pertinent to identity. However, our experiments reveal that while the face recognition backbone improves identity consistency, it lacks the semantic features required for editing. This task demands not only maintaining identity consistency but also incorporating the ability to edit, such as generating videos of faces with the same identity but varying age and makeup. Previous research \cite{Imagine_yourself, ID-Animator} relies solely on the CLIP encoder \cite{CLIP} to enable editing capabilities. However, since CLIP is not specifically trained on face datasets, the features it extracts include irrelevant non-face information, which can compromise identity fidelity \cite{photomaker, instantid, Ip-adapter}.

To address these challenges, we first use a facial recognition backbone to extract features that strongly represent intrinsic identity, and a CLIP image encoder to capture semantically rich features. We then employ the Q-Former \cite{blip1, blip2, blip3} to fuse these features, resulting in intrinsic identity representations enriched with high-frequency semantic information. To mitigate the impact of irrelevant features from CLIP, dropout \cite{drop_token, dropout} is applied post-processing. Additionally, we follow \cite{UniPortrait} to concatenate the shallow, multi-scale features from the facial recognition backbone (after interpolation) with the CLIP features. This approach ensures that the model captures essential intrinsic identity features while filtering out extraneous noise unrelated to identity. Finally, we apply cross-attention to facilitate interaction between this feature set and the visual tokens produced by each attention block of the pre-trained model, thereby enhancing the high-frequency information in the DiT:
\begin{equation}
Z_i^{\prime} = Z_i + \text{Attention}(Q_i^v, K_i^f, V_i^f),
\end{equation}
where $i$ represents the layer number of the attention block, $Q^{v} = Z_i W^{q}_i$, $K^{f} = F W^{k}_i$, and $V^{f} = F W^{v}_i$, where $Z_i$ is the visual token, $F$ represents the intrinsic identity features, and $W_q$, $W_k$, and $W_v$ are trainable parameters. The objective function is changed to:
{\small
\begin{equation}
\label{eq: local_loss_function}
\mathcal{L}_{c}=\mathbb{E}_{x_0, t, y, f, \epsilon}\left[\left\|\epsilon-\epsilon_\theta\left(x_0, t, \tau_\theta(y), \psi_\theta(f), \varphi_\theta(f)\right)\right\|_2^2\right],
\end{equation}
}where $\varphi_\theta(\cdot)$ is the local facial extractor.

