\vspace{-0.5em}
\begin{equation}
    \mathcal{L}_{f} = 
    -\frac{1}{B}\sum_{i=1}^{B}
    \mathrm{log}
    \frac{\sum_{\tilde{\mathbf{t}}\in \tilde{\mathbf{T}}_i} \exp (sim(\mathbf{f}, \tilde{\mathbf{t}}))}
    {\sum_{\tilde{\mathbf{t}}_* \in \{ \tilde{\mathbf{T}}_i \cup \tilde{\mathbf{T}}_{neg} \} } \mathrm{exp} (sim(\mathbf{f}, \tilde{\mathbf{t}}_*))}, 
