\paragraph{Negative log likelihood} Based on Assumption~\ref{assume:A1}, \ref{assume:A2}, we can construct the negative log likelihood (NLL) of the target label distribution $p_t(y=\cdot)=\vect{\pi}$ and ID data ratio $p_t(b=1)=\rho_t$ given target unlabeled data $\mathcal{D}^t$.
\begin{restatable}{lemma}{lemmaobj}
\label{lemma:obj}
    Under Assumption~\ref{assume:A1},~\ref{assume:A2}, given $\mathcal{D}^t$, the negative log likelihood ${-\log L(\vect{\pi},\rho_t;\mathcal{D}^t)}$ can be written as:
    \begin{equation}\label{eq:nll}
    \begin{aligned}
        %- \log L(\vect{\pi},\rho_t;\mathcal{D}^t) 
         %= & - \sum^{N^t}_{i=1} \log \Bigg(\frac{\rho_t}{\rho_s}h(x_i) \cdot \sum^K_{j=1}\frac{\pi_j}{c_j} f(x_i)_j \\
        % & +  \frac{1 - \rho_t}{1 - \rho_s} \cdot (1- h(x_i))\Bigg) + C, \\
        - \log L(\vect{\pi},\rho_t;\mathcal{D}^t) = - \sum^{N^t}_{i=1} \log \left(\sum^{K+1}_{j=1}\frac{\Tilde{\pi}_j}{\Tilde{c}_j} \Tilde{f}(x_i)_j \right) + C, \\
    \end{aligned}
    \end{equation}
    where $C$ does not depend on either $\vect{\pi}$ or $\rho_t$ and 
    \begin{equation}\label{eq:tilde-f}
    \Tilde{f}(x)_i := 
    \begin{cases}
    h(x)\cdot f(x)_i,  & i\in \mathcal{Y} \\
    1 - h(x), & i = K + 1,
    \end{cases},
\end{equation}
% and % \russ{``are irrelevant to'' $\to$ ``do not depend on''?} 
\begin{equation} \label{eq:tilde-pi-and-c}
\begin{aligned}
    \Tilde{\vect{\pi}} & := [\rho_t\cdot\pi_1,...,\rho_t\cdot\pi_K, 1 - \rho_t]^T \\
    \Tilde{\vect{c}} & := [\rho_s\cdot c_1, ...,\rho_s\cdot c_K, 1 - \rho_s]^T.
\end{aligned}
\end{equation}
\end{restatable}


