\begin{algorithm}[h]
\caption{MLE/MAP-OLS}
	\begin{algorithmic}
	    \label{alg:MAPOLS}
	    \STATE \textbf{Input: }$\mathcal{D}^t=\{x^t_i\}^{N^t}_{i=1}, \vect{c}, \rho_s, h(x), f(x)$,
        %\STATE \textbf{Options:} 
        \begin{itemize}
            \item MLE-OLS: $\vect{\alpha}^{\textbf{in}}=\vect{1}$, $\alpha_1^{\textbf{out}}, \alpha_2^{\textbf{out}}=\vect{1}$.
            \item MAP-OLS: $\vect{\alpha}^{\textbf{in}}\in\mathbb{R}^{K}_{> 1}$, $\alpha_1^{\textbf{out}}, \alpha_2^{\textbf{out}}\in\mathbb{R}_{> 1}$.
        \end{itemize}
	    \STATE \textbf{Initialize:} $\vect{\pi}^{(0)}\in \Delta^{K-1}_{>0}, \rho^{(0)}_t\in (0, 1)$.
        \STATE \textbf{Construct:} $\Tilde{f},\Tilde{c}$ based on~\eqref{eq:tilde-f},\eqref{eq:tilde-pi-and-c}.
		\FOR{$m=0$ to $M$}
        \STATE \textbf{Construct: } $\Tilde{\vect{\pi}}^{(m)}$ based on $\vect{\pi}^{(m)},\rho^{(m)}_t$ and ~\eqref{eq:tilde-pi-and-c}.
        \STATE \textbf{E-step:} For $j\in\mathcal{Y}\cup\{K+1\}$, evaluate
        \STATE\begin{equation}
                g_{ij}^{(m)} = \frac{\Tilde{\pi}^{(m)}_j/ \Tilde{c}_j \cdot \Tilde{f}(x^t_i)_j}{\sum^K_{l=1}\Tilde{\pi}^{(m)}_l/ \Tilde{c}_l \cdot \Tilde{f}(x^t_i)_l}.
            \end{equation}
        \STATE  \textbf{M-step:}  For $j\in\mathcal{Y}$, evaluate 
        \STATE \begin{equation}\label{alg-eq:M}
                \left\{
                \begin{aligned}  
                    \pi_j^{(m+1)} & = \frac{\sum^{N^t}_{i=1} g_{ij}^{(m)} + \alpha_j^{\textbf{in}} - 1}{N^t  - \sum^{N^t}_{i=1}g_{iK+1}^{(m)} + \sum^K_{l=1}(\alpha_l^{\textbf{in}} - 1)} \\
                    \rho_t^{(m+1)} &  = \frac{N^t  - \sum^{N^t}_{i=1}g_{iK+1}^{(m)} + \alpha_1^{\textbf{out}} - 1}{N^t + \alpha_1^{\textbf{out}} + \alpha_2^{\textbf{out}} - 2}.
                \end{aligned}
                \right.
                \end{equation}
		\ENDFOR
		\STATE \textbf{Output: } $p_t(y=\cdot)=\vect{\pi}^{(M+1)}, p_t(b=1)=\rho_t^{(M+1)}$.
	\end{algorithmic}  
\end{algorithm}  
