\textbf{Scope.} We study systems represented by autonomous differential equations (Eq.~\ref{eq:autonODE}), which depend only on the state variable captured in video. Assuming no external forces,
\begin{equation}
    z^{(n)}+ \gamma_{n} z^{(n-1)} + ... + \gamma_{2} z^{(1)} + \gamma_{1} z + \gamma_{0} = 0 |  z^{(k)} = \frac{d^{k}z}{dt^{k}}
   \label{eq:autonODE}
\end{equation}
is an $n^\textrm{th}$-order system, where $z$ is the time-dependent state variable or "dynamic variable", $z^{(k)}$ with $k = 1, 2,\dots n$  is the $k^\textrm{th}$-derivative of $z$ with respect to time $t$ and $\gamma_i$ with $i = 0,1,\dots n-1$ are the parameters of the equation we want to estimate. 

While our approach can be extended to equations of arbitrary order, in the following \emph{proof-of-concept}, we first consider a second-order differential equation since it is the maximum order used in previous work:
\begin{equation}
   z^{(2)}+ \gamma_1 z^{(1)} + \gamma_0 z = 0. 
   \label{eq:secondOrder}
\end{equation}


\noindent \textbf{Physics block.} Our physics block numerically solves the differential equation using a single step of Euler's method:
\begin{eqnarray}
\label{eq:eulers}
    &z^{(1)}_t \approx \frac{ z_{t+1} - z_{t} }{ \delta t  } \approx \frac{ z_{t} - z_{t-1} }{ \delta t  }  \\ [4pt]
    &z_{t+1} = z_{t} + \delta t   z^{(1)}_{t}   \\ [5pt]
    &z^{(1)}_{t+1} = z^{(1)}_{t} + \delta t z^{(2)}_{t}.
\end{eqnarray}
Plugging in Eq.~\ref{eq:secondOrder}, we can rewrite the physics block as:
\begin{equation}
   \hat{z}_{t+1} = z_{t} + \delta t \left( z^{(1)}_{t} - \delta t ( \gamma_1 z^{(1)}_t + \gamma_0 z_t ) \right).
   \label{eq:phys2or}
\end{equation}
\begin{equation*}
  P : \mathbb{R}^d \rightarrow \mathbb{R}^d,
\end{equation*}
\begin{equation}
   \hat{z}_{t+1} = P_\gamma(z_{t}, .. z_{t-n}; \bf{\gamma} ).
   \label{eq:physblock}
\end{equation}
where $\gamma_i$ are learnable parameters and the predicted latent space $\hat{z}$ for time $t+1$ is a function $P_\gamma(\cdot  )$ of the latent representations of the $n$ previous frames. We use the notation $ \mathbf{\hat{z}}$ for the latent space predicted using the function $P$, which is different from $\mathbf{z}$ predicted by the encoder. 

\noindent \textbf{Encoder.} The encoder is a network $E_\theta(x)$ that maps images $x \in \mathbb{R}^{w\times h \times  c}$ to the state variable $z \in \mathbb{R}^d$, where $d$ is the number of dynamic variables. We use an MLP, similar to~\cite{jaques2019physics} suitable as localization networks, with three layers and the ReLU activation function for the mapping
\begin{eqnarray}
  z_t  = E_\theta(x_t), \quad  \text{where} &E : \mathbb{R}^{w\times h \times  c} \rightarrow \mathbb{R}^d. 
   \label{eq:E}
\end{eqnarray}


